(()=>{"use strict";(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,54775,74614,94599,30367,89470,28023,6625,e=>{let t,s,a,o,i=(e,t,s)=>({name:e,type:t,power:s}),r=[{id:"bs-counter",kind:"bugspot",prompt:"Two threads run worker() at the same time. Tap the line that causes a lost update.",lines:["int counter = 0;","pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;","","void *worker(void *arg) {","    for (int i = 0; i < 100000; i++) {","        counter++;","    }","    return NULL;","}","/* main starts two workers, joins both, prints counter */"],answer:[5],explain:"counter++ is a read-modify-write: load, add, store. Two threads can both load the same value and each store value+1, so one increment is lost and the total comes out below 200000. The mutex is declared but never taken. Wrapping the increment in pthread_mutex_lock/unlock (or using an atomic add) makes it indivisible.",move:i("Race Catch","sync",36)},{id:"bs-toctou",kind:"bugspot",prompt:"This function runs in a privileged program. Tap the two lines that form a time-of-check to time-of-use race.",lines:["int save_report(const char *path, const char *text) {","    if (access(path, W_OK) != 0) {","        return -1;","    }","    /* the file system can change between the check and the open */",'    FILE *f = fopen(path, "w");',"    if (f == NULL) return -1;","    fputs(text, f);","    fclose(f);","    return 0;","}"],answer:[1,5],explain:"access() checks the path, and fopen() later uses it, but nothing makes the pair atomic. In the gap another process can replace the file with a symlink to something sensitive, so the privileged program writes where the user was never allowed to. The fix is to skip the check and just open (with O_NOFOLLOW if needed), letting the kernel enforce permissions at the moment of use.",move:i("Gap Strike","sync",38)},{id:"bs-cond-if",kind:"bugspot",prompt:"take() should block until an item exists. Tap the line that breaks on spurious wakeups or a stolen item.",lines:["pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;","pthread_cond_t  ready = PTHREAD_COND_INITIALIZER;","int items = 0;","","void take(void) {","    pthread_mutex_lock(&m);","    if (items == 0)","        pthread_cond_wait(&ready, &m);","    items--;","    pthread_mutex_unlock(&m);","}"],answer:[6],explain:"The condition must be rechecked after every wakeup, so the test belongs in a while loop. With if, a spurious wakeup, or another consumer that took the item between the signal and this thread reacquiring the mutex, leaves items at 0 and items-- drives it to -1. The pattern is always: while (!predicate) pthread_cond_wait(...).",move:i("Loop Guard","sync",36)},{id:"bs-lock-order",kind:"bugspot",prompt:"The house rule is: always lock a before b. Tap the line that can deadlock with t1().",lines:["pthread_mutex_t a, b;   /* lock order: always a, then b */","void *t1(void *arg) {","    pthread_mutex_lock(&a);","    pthread_mutex_lock(&b);","    /* update both */","    pthread_mutex_unlock(&b);","    pthread_mutex_unlock(&a);","}","void *t2(void *arg) {","    pthread_mutex_lock(&b);","    pthread_mutex_lock(&a);","    /* update both */","    pthread_mutex_unlock(&a);","    pthread_mutex_unlock(&b);","}"],answer:[9],explain:"t1 holds a and waits for b while t2 holds b and waits for a: a circular wait, so both block forever. Breaking one of the four Coffman conditions fixes it, and the cheap way is a global lock order. t2 takes b first, which violates the order; taking a first (as t1 does) makes a cycle impossible.",move:i("Order Break","sync",38)},{id:"bs-early-return",kind:"bugspot",prompt:"Tap the line that returns while still holding the lock.",lines:["pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;","int table[64];","","int lookup(int key) {","    pthread_mutex_lock(&m);","    int idx = key & 63;","    if (table[idx] == 0) {","        return -1;","    }","    int v = table[idx];","    pthread_mutex_unlock(&m);","    return v;","}"],answer:[7],explain:"The early return skips pthread_mutex_unlock, so the first lookup of a missing key leaves the mutex locked forever and every later caller blocks. Release the lock on every exit path: unlock before returning (or funnel all exits through one cleanup label).",move:i("Held Lock","sync",34)},{id:"bs-dcl",kind:"bugspot",prompt:"This double-checked locking has no memory ordering. Tap the two lines that need acquire/release semantics.",lines:["struct config *cfg = NULL;","pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;","","struct config *get_config(void) {","    if (cfg == NULL) {","        pthread_mutex_lock(&m);","        if (cfg == NULL) {","            cfg = load_config();","        }","        pthread_mutex_unlock(&m);","    }","    return cfg;","}"],answer:[4,7],explain:"The unlocked read at the first check races with the store inside the lock. Without release on the store and acquire on the read, the compiler or CPU may publish the pointer before the fields of the new struct are visible, so another thread sees a non-NULL cfg pointing at half-initialized data. Declaring cfg as an atomic pointer and storing with release / loading with acquire (or just using pthread_once) fixes it.",move:i("Fence Post","sync",40)},{id:"bs-lost-signal",kind:"bugspot",prompt:"If producer() runs before consumer(), consumer() sleeps forever. Tap the two lines that make the wakeup get lost.",lines:["pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;","pthread_cond_t  cv = PTHREAD_COND_INITIALIZER;","","void *producer(void *arg) {","    pthread_mutex_lock(&m);","    pthread_cond_signal(&cv);","    pthread_mutex_unlock(&m);","    return NULL;","}","void *consumer(void *arg) {","    pthread_mutex_lock(&m);","    pthread_cond_wait(&cv, &m);","    pthread_mutex_unlock(&m);","    return NULL;","}"],answer:[5,11],explain:"A condition variable has no memory: a signal sent while nobody waits is discarded. The code keeps no state, so the producer signals into the void and the consumer later waits for a notification that already happened. Record the event in a shared flag (set it under the lock before signalling) and make the consumer wait with while (!flag) pthread_cond_wait(...).",move:i("Missed Call","sync",38)},{id:"bs-ring-index",kind:"bugspot",prompt:"put() is called with the lock held and the buffer is drained by get(). Tap the line that eventually writes past the end of buf.",lines:["#define N 8","int buf[N];","int in = 0;      /* next slot to write */","int count = 0;   /* items stored */","","void put(int x) {","    if (count == N) return;      /* full */","    buf[in] = x;","    in = in + 1;","    count++;","}"],answer:[8],explain:"A ring buffer must wrap its index: in = (in + 1) % N. Here in only grows, so after eight puts the next write goes to buf[8], beyond the array, even though get() has freed slots and count is below N. The out-of-bounds store corrupts neighbouring memory. The full check is correct; the index update is the bug.",move:i("Overrun","memory",38)},{id:"bs-fork-fail",kind:"bugspot",prompt:"Tap the line that goes wrong if fork() fails and returns -1.",lines:["int run_ls(void) {","    pid_t pid = fork();","    if (pid == 0) {",'        execl("/bin/ls", "ls", "-l", (char *)NULL);',"        _exit(127);","    }","    waitpid(pid, NULL, 0);","    return 0;","}"],answer:[6],explain:"fork() returns -1 when it cannot create a process (process limit, out of memory), and the code never checks for it. Then the parent branch runs with pid = -1, and waitpid(-1, ...) waits for any child (or fails with ECHILD) and run_ls reports success although nothing ran. Handle the three cases explicitly: pid < 0 is an error, pid == 0 is the child, pid > 0 is the parent.",move:i("Fork Fail","process",34)},{id:"bs-double-close",kind:"bugspot",prompt:"Tap the line that closes a file descriptor that is already closed.",lines:["int copy_file(const char *src, const char *dst) {","    int in = open(src, O_RDONLY);","    int out = open(dst, O_WRONLY | O_CREAT, 0644);","    char buf[4096];","    ssize_t n;","    while ((n = read(in, buf, sizeof buf)) > 0)","        write(out, buf, n);","    close(in);","    close(out);","    close(in);","    return 0;","}"],answer:[9],explain:"After close(in) the descriptor number is free, and the kernel hands the lowest free number to the next open(). A second close(in) therefore fails with EBADF at best, and in a multi-threaded program it can silently close a different file another thread just opened under the same number. Close each descriptor exactly once, and set it to -1 afterwards.",move:i("Stale Handle","io",34)}];e.s(["f",0,r],54775);let n=(e,t,s)=>({name:e,type:t,power:s}),l=[{id:"fill-bb-sem",kind:"fill",prompt:"Bounded buffer with semaphores (empty starts at N, full at 0, mutex at 1). Complete producer() so it neither overflows the buffer nor deadlocks.",lines:["void producer(void) {","    while (1) {","        int item = produce();","        ___1___;","        sem_wait(&mutex);","        put(item);","        sem_post(&mutex);","        ___2___;","    }","}"],blanks:[{options:["sem_wait(&empty)","sem_wait(&full)","sem_post(&empty)"],answer:0},{options:["sem_post(&full)","sem_post(&empty)","sem_wait(&full)"],answer:0}],explain:"The producer must first claim a free slot: sem_wait(&empty) blocks when all N slots are full. After inserting, it announces one more filled slot with sem_post(&full), which wakes a waiting consumer. Waiting on empty while holding the mutex would deadlock, which is why the order is empty, then mutex.",move:n("Semaphore Gate","sync",38)},{id:"fill-bb-cv",kind:"fill",prompt:"Bounded buffer with a mutex and two condition variables (not_full, not_empty). Complete the consumer so it is correct even with spurious wakeups and several consumers.",lines:["int get(void) {","    pthread_mutex_lock(&m);","    ___1___ (count == 0)","        pthread_cond_wait(&not_empty, &m);","    int item = buf[out];","    out = (out + 1) % N;","    count--;","    ___2___;","    pthread_mutex_unlock(&m);","    return item;","}"],blanks:[{options:["if","for (;;) if","while"],answer:2},{options:["pthread_cond_signal(&not_full)","pthread_cond_signal(&not_empty)","pthread_cond_wait(&not_full, &m)"],answer:0}],explain:"Use while: after waking, another consumer may already have taken the item, and wakeups can be spurious, so the condition must be re-checked with the mutex held. Having removed an item, the consumer frees a slot, so it signals not_full to wake a blocked producer. Signalling not_empty would wake a consumer for nothing, and waiting here would block with no reason.",move:n("Condvar Loop","sync",40)},{id:"fill-rw",kind:"fill",prompt:"Readers-writers, reader preference. rw guards the data, mutex guards readcount. Complete reader_enter() so that the first reader locks writers out and later readers share.",lines:["void reader_enter(void) {","    sem_wait(&mutex);","    readcount++;","    if (readcount == ___1___)","        ___2___;","    sem_post(&mutex);","}","void reader_exit(void) {","    sem_wait(&mutex);","    readcount--;","    if (readcount == 0)","        sem_post(&rw);","    sem_post(&mutex);","}"],blanks:[{options:["0","1","2"],answer:1},{options:["sem_post(&rw)","sem_wait(&mutex)","sem_wait(&rw)"],answer:2}],explain:"After readcount++ the first reader sees 1. Only that reader does sem_wait(&rw), blocking writers for as long as any reader is inside; the last reader out (readcount back to 0) posts rw. Every reader locking rw would serialize readers, and waiting on mutex again would self-deadlock.",move:n("Shared Lock","sync",38)},{id:"fill-philosophers",kind:"fill",prompt:"Dining philosophers: five forks, philosopher i uses forks i and (i+1)%5. Complete the pickup order that breaks the circular wait.",lines:["void philosopher(int i) {","    int a = i, b = (i + 1) % 5;","    while (1) {","        think();","        if (___1___) { int t = a; a = b; b = t; }","        sem_wait(&fork[a]);","        sem_wait(&fork[b]);","        eat();","        ___2___;","        sem_post(&fork[b]);","    }","}"],blanks:[{options:["a > b","a != b","a == b"],answer:0},{options:["sem_wait(&fork[a])","sem_post(&fork[a])","sem_post(&fork[i + 1])"],answer:1}],explain:"Swapping so that a is always the lower-numbered fork makes every philosopher take the lower fork first (philosopher 4 swaps to forks 0 then 4). A global resource ordering means no cycle of waits can form, so no deadlock. Afterwards both forks must be released, here fork[a] and fork[b].",move:n("Ordered Forks","sync",42)},{id:"fill-barrier",kind:"fill",prompt:"A reusable-once barrier for N threads using a counter and a condition variable. Complete barrier_wait() so no thread leaves before all N have arrived.",lines:["void barrier_wait(void) {","    pthread_mutex_lock(&m);","    arrived++;","    if (arrived == N) {","        ___1___;","    } else {","        while (arrived < N)","            ___2___;","    }","    pthread_mutex_unlock(&m);","}"],blanks:[{options:["pthread_cond_signal(&all)","pthread_cond_wait(&all, &m)","pthread_cond_broadcast(&all)"],answer:2},{options:["pthread_cond_wait(&all, &m)","pthread_cond_signal(&all)","pthread_mutex_unlock(&m)"],answer:0}],explain:"The last thread to arrive must wake all N-1 sleepers, so it uses pthread_cond_broadcast; signal would release only one and leave the rest asleep forever. The early arrivals sleep in pthread_cond_wait, which atomically releases the mutex while waiting and re-takes it on wakeup, inside a while loop that re-checks arrived < N.",move:n("Rally Point","sync",40)},{id:"fill-once",kind:"fill",prompt:"One-time initialization shared by many threads. Complete get_config() so init runs exactly once and every caller sees the finished config.",lines:["static int done = 0;","static config_t cfg;","static pthread_mutex_t m = PTHREAD_MUTEX_INITIALIZER;","","config_t *get_config(void) {","    pthread_mutex_lock(&m);","    if (___1___) {","        init(&cfg);","        ___2___;","    }","    pthread_mutex_unlock(&m);","    return &cfg;","}"],blanks:[{options:["done","!done","done < 0"],answer:1},{options:["done = 0","pthread_mutex_unlock(&m)","done = 1"],answer:2}],explain:"Under the mutex, check that init has not yet happened (!done), run it, then record that with done = 1. Because the check and the update are both inside the critical section, exactly one thread initializes and later callers see done == 1. (pthread_once does the same job without the lock cost on later calls.)",move:n("Once Only","sync",36)}];e.s(["f",0,l],74614);let h=(e,t,s)=>({name:e,type:t,power:s}),d=[{id:"inc-io-wait",kind:"incident",prompt:"Page at 02:10: the orders API times out. The database host shows a load average near 15, yet the on-call dashboard says the CPUs look idle. You SSH in and run a few tools.",outputs:[{cmd:"top -bn1 | head -5",text:"top - 02:11:40 up 41 days,  load average: 14.82, 13.97, 9.40\nTasks: 211 total,   1 running, 210 sleeping,   0 zombie\n%Cpu(s):  3.1 us,  2.0 sy,  0.0 ni, 11.9 id, 83.0 wa,  0.0 hi\nMiB Mem :  15880 total,    402 free,     20 buffers,   1849 cache\nMiB Swap:   4096 total,   4096 free,      0 used"},{cmd:"vmstat 1 3",text:"procs ------memory------ --swap-- ---io--- -system- ------cpu-----\n r  b   swpd   free   si   so    bi    bo   in   cs us sy id wa st\n 1 14      0 412344    0    0 18420   310 2210 4120  3  2 12 83  0\n 0 14      0 412120    0    0 19110   285 2188 4098  2  2 11 85  0\n 1 13      0 411986    0    0 18760   402 2240 4155  3  2 13 82  0"},{cmd:"ps -eo state,pid,comm | sort | uniq -c -w1",text:"      1 R  4412 top\n    196 S  1 systemd\n     14 D  3107 postgres"}],steps:[{ask:"What is the bottleneck?",options:["The CPUs are saturated","Disk I/O: tasks are blocked waiting for storage","Memory is exhausted and the host is swapping","A runaway process is leaking file descriptors"],answer:1,why:"us+sy is only 5% and idle is about 12%, so the CPUs are not busy. But wa is 83%, vmstat shows b=14 tasks blocked, bi is about 18,000 blocks/s and ps shows 14 postgres processes in D state. Swap is untouched (si/so = 0), so it is not paging."},{ask:"Which tool do you run next?",options:["iostat -x 1, to see which device has high await and %util","perf top, to find the hot function","free -m, to look for a memory leak","strace -c on PID 1"],answer:0,why:"The wait is on storage, so you need the per-device view: await (latency per request), queue size and %util show whether one disk is saturated. perf top and strace look at CPU and system calls, which are idle here."},{ask:"kill -9 on the 14 stuck postgres processes does nothing. Why?",options:["postgres traps SIGKILL","They are zombies, which are already dead","Only the parent can kill a child","The processes are in uninterruptible sleep (D) and only act on signals when the I/O completes"],answer:3,why:"State D is uninterruptible sleep: the task is inside the kernel waiting for a disk request and cannot be woken by a signal, SIGKILL included, until the I/O finishes. SIGKILL cannot be trapped, and these are not zombies (the zombie count is 0)."}],explain:"High load with idle CPU is the classic signature of I/O wait: Linux counts tasks in D state in the load average, so load rises while us+sy stay low. Read wa and b in vmstat, confirm D states in ps, then drill into the device with iostat.",move:h("Triage","io",30)},{id:"inc-oom",kind:"incident",prompt:"Page at 14:52: the search service restarts every few hours with no crash report. Latency climbs for an hour before each restart. You log in to the host right after the latest one.",outputs:[{cmd:"dmesg -T | grep -i -A2 'out of memory'",text:"[Tue 14:51:07] Out of memory: Killed process 8123 (indexer)\n  total-vm:31457280kB, anon-rss:15728640kB, file-rss:0kB\n[Tue 14:51:07] oom_reaper: reaped process 8123 (indexer)"},{cmd:"free -m",text:"              total   used   free  shared  buff/cache  available\nMem:          16384  15902    118       4         364        161\nSwap:             0      0      0"},{cmd:"ps -eo pid,rss,etimes,comm --sort=-rss | head -3",text:"    PID     RSS ELAPSED COMMAND\n   9040 15481212    3011 indexer\n   1722   188340  901234 postgres"}],steps:[{ask:"What killed the service?",options:["A segfault in the indexer","systemd stopped it for a failed health check","The kernel OOM killer reclaimed memory after RAM ran out with no swap","The disk filled up"],answer:2,why:"dmesg shows 'Out of memory: Killed process 8123 (indexer)' with anon-rss of 15 GB on a 16 GB host. free shows 118 MB free and only 161 MB available (the cache is just 364 MB, so there is nothing cheap to drop) and swap is 0, so the kernel had no other way to get memory back."},{ask:"What do you check next to find the cause?",options:["Reboot the host to clear memory","Whether the new indexer is already growing: sample its RSS over time (ps, /proc/PID/status or smem)","Raise vm.swappiness","Run fsck on the data disk"],answer:1,why:"The replacement indexer (PID 9040) already has 15 GB RSS only 3011 s (50 min) after starting, so it grows without bound. Sampling its RSS (and a heap profile) shows the rate and confirms a leak. Swappiness is irrelevant with no swap, and a reboot only resets the clock."},{ask:"Which change makes the failure safe while the leak is being fixed?",options:["Run the indexer in a cgroup with a memory limit (and restart policy) so only it is killed and the host stays healthy","Turn off the OOM killer","Lower the indexer's nice value","Add more CPU cores"],answer:0,why:"A cgroup memory.max limit makes the OOM kill happen inside the group, at a predictable size, instead of the host running out and the kernel choosing a victim. Disabling the OOM killer would let allocations stall the machine, and nice or cores affect CPU, not memory."}],explain:"A process whose RSS grows until RAM is gone is killed by the kernel OOM killer; the evidence is the 'Out of memory: Killed process' line in dmesg plus near-zero free and available memory. Confirm the leak by watching RSS grow, then contain it with a cgroup limit.",move:h("Triage","memory",30)},{id:"inc-zombies",kind:"incident",prompt:"Page at 09:30: the job runner can no longer start new jobs ('fork: Resource temporarily unavailable'). CPU and memory look fine. You check the process table.",outputs:[{cmd:"ps -eo pid,ppid,stat,comm | awk '$3 ~ /Z/' | head -4",text:"  5101  2210 Z    job <defunct>\n  5102  2210 Z    job <defunct>\n  5103  2210 Z    job <defunct>\n  ..."},{cmd:"ps -eo stat | sort | uniq -c",text:"      3 R\n    240 S\n  32520 Z"},{cmd:"cat /proc/sys/kernel/pid_max; ps -p 2210 -o pid,stat,comm",text:"32768\n  PID STAT COMMAND\n 2210 Sl   runner"}],steps:[{ask:"What are the 32,520 Z processes?",options:["Processes stuck waiting for disk I/O","Processes swapped out to disk","Threads spinning on a lock","Children that have exited but whose parent has not called wait() to collect their exit status"],answer:3,why:"State Z with <defunct> is a zombie: the process has exited and only its process-table entry remains until the parent reads the exit status with wait()/waitpid(). All of them share PPID 2210, the runner, which is alive in state Sl (sleeping) and is not reaping."},{ask:"Why does fork() fail now, with CPU and RAM idle?",options:["Zombies use all the CPU","Zombies hold 4 GB of memory each","The kernel has run out of PIDs: 32,520 zombies plus 243 live tasks use 32,763 of the 32768 PIDs allowed by pid_max","fork is disabled once the load average passes 10"],answer:2,why:"Each zombie still owns a PID. 32,520 + 243 live tasks is 32,763 of the 32,768 PIDs in use (the last few are reserved or taken by short-lived commands), so no PID is free and fork returns EAGAIN. Zombies hold essentially no memory or CPU, which is why those graphs look fine."},{ask:"What is the real fix?",options:["kill -9 each zombie","Make the runner reap children (wait()/waitpid in a SIGCHLD handler, or SIGCHLD set to SIG_IGN); killing the runner also lets init adopt and reap the zombies","Raise the nice value of the runner","Reboot every night"],answer:1,why:"A zombie is already dead, so SIGKILL has nothing to kill. Only the parent's wait() frees the entry. Fix the runner's code; as an immediate remedy, terminate the runner, because orphaned zombies are re-parented to init (PID 1), which reaps them immediately."}],explain:"Zombies cost a PID and a process-table slot, not CPU or memory, but enough of them exhaust pid_max and make fork fail. The cure is in the parent: reap with waitpid in a SIGCHLD handler, or exit the parent so init adopts them.",move:h("Triage","process",30)},{id:"inc-pool-deadlock",kind:"incident",prompt:"Page at 16:05: after a traffic spike the checkout service stops answering. Nothing crashed and the host is nearly idle, but every request hangs until the load balancer times out. A restart fixes it for a few minutes.",outputs:[{cmd:"top -bn1 | head -4",text:"top - 16:06:12 up 9 days,  load average: 0.12, 0.40, 0.22\nTasks: 188 total,   0 running, 188 sleeping,   0 zombie\n%Cpu(s):  0.4 us,  0.2 sy,  0.0 ni, 99.3 id,  0.1 wa\nMiB Mem :  15880 total,  9120 free,  2210 used,  4550 cache"},{cmd:"ps -L -o tid,stat,wchan:20,comm -p 3301 | head -6",text:"  TID STAT WCHAN                COMMAND\n 3301 Sl   futex_wait_queue     checkout\n 3340 Sl   futex_wait_queue     pool-1-worker-1\n 3341 Sl   futex_wait_queue     pool-1-worker-2\n 3342 Sl   futex_wait_queue     pool-1-worker-3\n 3343 Sl   futex_wait_queue     pool-1-worker-4"},{cmd:"thread dump (all 4 workers identical)",text:'"pool-1-worker-1" WAITING\n  at Future.get(Future.java:193)\n  at CheckoutService.price(CheckoutService.java:58)\n  at CheckoutService.handle(CheckoutService.java:31)\n  at ThreadPoolExecutor.runWorker(...)\nqueue: 37 pending tasks (pool size 4, all 4 busy)'}],steps:[{ask:"What does the output say about the problem?",options:["The process is blocked, not busy: every worker waits on a futex (a lock or condition) with the CPU 99% idle","The CPUs are saturated","The disk is slow","The kernel is out of memory"],answer:0,why:"Load is 0.12 and idle is 99.3%, so nothing is computing. Every worker thread is in futex_wait_queue, the kernel wait used by locks and condition variables, and wa is 0.1 so it is not disk either. Memory is 9 GB free."},{ask:"What is the root cause?",options:["A data race corrupts the queue","The load balancer is broken","The futex syscall is slow","Thread-pool starvation deadlock: each of the 4 workers runs handle(), which submits price() to the same pool and blocks in Future.get() for it, but the sub-task sits in the queue behind them and no worker is free to run it"],answer:3,why:"The dump shows workers inside handle() blocked at Future.get() in price(). With 4 workers all blocked and 37 tasks pending, the awaited sub-tasks can never run. It is a circular wait: workers need queue progress, and queue progress needs a free worker. It only appears under load, when all workers are busy at once."},{ask:"Which fix removes the deadlock?",options:["Retry the request in a loop","Increase the pool to 5 threads and hope","Do not block a pool thread waiting for work queued on the same pool: use a separate pool for the sub-tasks, make it asynchronous (composition/callbacks), or run price() inline","Lower the thread priority"],answer:2,why:"The wait must not depend on a resource (a free worker) held by the waiters. A separate pool or a non-blocking continuation breaks the cycle. A bigger pool only moves the threshold: 5 workers deadlock once 5 requests arrive together."}],explain:"Idle CPU with every thread in futex wait and a growing queue means threads are blocked on each other. Nested blocking submits to a bounded pool create a hold-and-wait cycle. Break it by never waiting for a queued sub-task from inside the same pool.",move:h("Triage","sync",30)},{id:"inc-ctx-storm",kind:"incident",prompt:"Page at 16:05: after a traffic spike the gateway's latency tripled, and the 8-core host is pegged, yet throughput barely moved. The service spawns one thread per request. You check the host.",outputs:[{cmd:"vmstat 1 3",text:"procs ------memory------ --swap-- ---io--- -system- ------cpu-----\n  r  b   swpd   free   si   so    bi    bo     in     cs us sy id wa st\n212  0      0 6120344    0    0     4    22  98210 186400 31 64  5  0  0\n206  0      0 6118120    0    0     0    18  97650 184900 32 63  5  0  0\n215  0      0 6117002    0    0     2    30  99020 188100 30 65  5  0  0"},{cmd:"nproc; ps -eLf | wc -l",text:"8\n4106"},{cmd:"pidstat -w -t -p 7331 1 1 | head -5",text:"  TID   cswch/s nvcswch/s Command\n 7331      0.00      0.00 gateway\n 7502     14.00    310.00 |__gateway\n 7503     11.00    298.00 |__gateway"}],steps:[{ask:"What is the bottleneck?",options:["Disk I/O","The CPUs are saturated, but mostly in the kernel: 64% sy with about 186,000 context switches per second","Memory is exhausted","The network card is dropping packets"],answer:1,why:"Idle is 5% and wa is 0, so the CPUs are fully busy, yet sy (64%) dwarfs us (31%): most of the time goes to the kernel, not to the application. The run queue r is about 210 on 8 cores, and cs is about 186,000/s. Swap and I/O columns are zero and 6 GB is free."},{ask:"Which counter shows why so many switches happen?",options:["The per-thread voluntary and involuntary counts from pidstat -w: nvcswch/s is far higher than cswch/s","free -m","df -h","ulimit -n"],answer:0,why:"A voluntary switch (cswch) is a thread blocking; an involuntary one (nvcswch) is the scheduler preempting a thread that was still runnable. Each gateway thread has about 300 involuntary and about 12 voluntary switches per second: the threads are runnable and fighting for 8 cores, not waiting on I/O."},{ask:"What is the root cause and fix?",options:["Too few threads: add more","The kernel needs a reboot","The scheduler quantum is too long: nothing to change","Thread-per-request created about 4,100 threads for 8 cores: run queue length and switching overhead eat the CPU. Bound the concurrency with a pool of roughly one to two times the cores (or an event loop) and queue the rest"],answer:3,why:"With 4,106 threads and r near 210 there are about 26 runnable threads per core, so every quantum ends in a preemption and a switch, which costs direct time and cold caches and TLBs. A bounded pool matched to the cores does the same work with far fewer switches, and a queue absorbs the spike."}],explain:"High sy, a run queue far above the core count and a huge cs rate with mostly involuntary switches mean too many runnable threads. Bound concurrency near the number of cores instead of spawning a thread per request.",move:h("Triage","scheduler",30)},{id:"inc-swap-thrash",kind:"incident",prompt:"Page at 11:20: the analytics box is crawling. Shell commands take seconds to start and the batch job's progress has almost stopped. Nobody deployed anything, but a new report started an hour ago.",outputs:[{cmd:"free -m",text:"              total   used   free  shared  buff/cache  available\nMem:          16384  16190     96       2          98         61\nSwap:          8192   8104     88"},{cmd:"vmstat 1 3",text:"procs ------memory------ --swap-- ---io--- -system- ------cpu-----\n r  b   swpd   free   si   so    bi    bo   in   cs us sy id wa st\n 2 19 8300544  98304 21440 23610 21800 24100 1450 2900  4  6 31 59  0\n 1 21 8301120  97800 22100 22980 22400 23500 1432 2870  3  7 30 60  0\n 3 20 8300960  98112 20980 24220 21100 24800 1465 2940  4  6 29 61  0"},{cmd:"top -bn1 -o %MEM | head -10 | tail -3",text:"  PID USER  RES   S %CPU %MEM COMMAND\n 6611 etl   14.6g D  3.0 91.2 report-gen\n   54 root     0   D  5.9  0.0 kswapd0"}],steps:[{ask:"What is happening?",options:["The CPUs are saturated","The disk is failing","Thrashing: the working set no longer fits in RAM, so the kernel constantly swaps pages out and back in","A network outage"],answer:2,why:"Available memory is 61 MB and swap is 8,104 of 8,192 MB used. vmstat shows si and so of about 21,000 and 23,000 KB/s at the same time (pages leave and return in the same second), b=20 blocked tasks and wa near 60%. Only 7% of the CPU is busy, and kswapd0 is active in D state."},{ask:"Which process is the culprit?",options:["kswapd0, because it is the busiest kernel thread","report-gen: it has 14.6 GB resident, 91% of memory, so its working set pushes everything else out","systemd","The shell, because it is slow to start"],answer:1,why:"kswapd0 is only the reclaim thread doing the paging, a symptom. The memory is held by report-gen at 14.6 GB RES (91.2% of RAM). Because it keeps touching its pages, they are swapped back in constantly, and the shell is slow because its own pages were evicted too."},{ask:"Which action fixes it, rather than hiding it?",options:["Shrink the working set (process the report in chunks or lower its memory limit), or add RAM; bigger swap only makes the thrashing last longer","Add a larger swap file","Raise the priority of kswapd0","Run sync and drop the page cache"],answer:0,why:"The demand for resident pages exceeds RAM, and disk is about 100,000 times slower than memory, so more swap does not help. Reduce what the job needs at once, or give the machine more RAM. The page cache is already only 98 MB, so dropping it frees nothing."}],explain:"Simultaneous heavy swap-in and swap-out, near-zero available memory, many tasks blocked and high wa mean thrashing. The cure is to make the working set fit in RAM, not to enlarge the swap.",move:h("Triage","memory",30)},{id:"inc-emfile",kind:"incident",prompt:"Page at 09:40: a web proxy that ran fine for weeks starts refusing new connections. Existing clients are fine, CPU and memory are quiet, and the error log has a line you have not seen before.",outputs:[{cmd:"tail -3 /var/log/proxy.log",text:"09:38:51 accept4: Too many open files\n09:38:51 accept4: Too many open files\n09:38:52 open(/etc/proxy/tls.pem): Too many open files"},{cmd:"grep 'open files' /proc/2290/limits; ls /proc/2290/fd | wc -l",text:"Max open files            1024                 1048576              files\n1024"},{cmd:"lsof -p 2290 | awk '{print $5}' | sort | uniq -c; ss -s | head -2",text:"      1 TYPE\n     12 REG\n      3 CHR\n    236 IPv4\n    773 sock\nTotal: 1031\nTCP:   1004 (estab 236, closed 0, orphaned 0, timewait 0)"}],steps:[{ask:"What does the output say about the failure?",options:["The machine is out of memory","The disk is full","The system-wide file table is full","The process hit its per-process file-descriptor limit: 1024 open of a soft limit of 1024, so accept4() and open() fail with EMFILE"],answer:3,why:'The log says "Too many open files" (EMFILE) from accept4 and open, and /proc/2290/limits shows a soft limit of 1024 with exactly 1024 entries in /proc/2290/fd. Memory and CPU are quiet, and the failing call is on a descriptor, not on disk space. The hard limit is 1,048,576, so the soft limit is the one being hit.'},{ask:"Why is the descriptor count so high for only 236 live clients?",options:["Each client needs four descriptors","The kernel keeps closed sockets for a minute","A descriptor leak: 773 sockets are open that are not established connections, so the code is not calling close() on some path (an error branch or a finished upstream connection)","lsof counts every thread separately"],answer:2,why:"lsof shows 236 IPv4 sockets, matching the 236 established connections in ss, plus 773 further sock entries that are not live connections (ss counts only 236 established and no orphaned or TIME_WAIT sockets). Those are descriptors the process still holds for connections it no longer uses. 12 + 3 + 236 + 773 = 1,024, exactly the open-file limit."},{ask:"What is the right fix?",options:["Only raise the limit with ulimit -n 1048576 and move on","Find and fix the missing close() (for example close in a finally/defer on every path) and monitor the fd count; raising the limit may be a stopgap, but a leak will fill any limit","Restart the proxy every night and keep the limit","Disable TLS so there are fewer files"],answer:1,why:"A bigger limit only delays the failure, because descriptors keep leaking at the same rate. Closing the descriptor on every path, preferably with RAII/defer/try-with-resources, removes the cause. Alerting on /proc/<pid>/fd count against the limit catches a regression early."}],explain:"EMFILE with a descriptor count equal to the soft limit means the per-process limit is reached. Sockets that outnumber live connections point to a missing close(), so fix the leak rather than only raising ulimit.",move:h("Triage","io",30)},{id:"inc-spinlock",kind:"incident",prompt:"Page at 14:15: a 4-core worker has been at 100% CPU for ten minutes, but request throughput fell to a trickle. The load is not from traffic, which is down. You look at which threads are burning CPU.",outputs:[{cmd:"top -H -bn1 -p 5180 | head -12 | tail -5",text:"  PID USER  S  %CPU  COMMAND\n 5192 svc   R  99.9  worker-2\n 5193 svc   R  99.7  worker-3\n 5194 svc   R  99.8  worker-4\n 5191 svc   R  99.6  worker-1"},{cmd:"vmstat 1 3",text:"procs ------memory------ --swap-- ---io--- -system- ------cpu-----\n r  b   swpd   free   si   so    bi    bo   in   cs us sy id wa st\n 4  0      0 9120344    0    0     0     2  310  420 99  1  0  0  0\n 4  0      0 9120344    0    0     0     0  305  415 99  1  0  0  0\n 4  0      0 9120344    0    0     0     0  308  418 98  2  0  0  0"},{cmd:"perf top -p 5180 -d 1 --stdio | head -4",text:"Overhead  Shared Object  Symbol\n  97.40%  libcache.so    [.] spin_lock_acquire\n   1.20%  libcache.so    [.] cache_lookup\n   0.80%  [kernel]       [k] native_queued_spin_lock_slowpath"}],steps:[{ask:"What does the CPU data say?",options:["The workers are runnable and burning user-mode CPU (99% us, almost no context switches and no I/O wait), yet making almost no progress","The workers are blocked on I/O","The kernel is the bottleneck","The system is swapping"],answer:0,why:"All four threads are in state R at about 99.7% CPU, vmstat shows us 98-99% with sy 1-2, wa 0 and b 0, and only about 420 context switches per second. They are not sleeping or waiting for the disk; they are executing instructions in user space without finishing requests."},{ask:"What does perf show?",options:["The time is in cache_lookup, so the cache is slow","perf shows nothing useful","The time is in the kernel scheduler","97% of the samples are in spin_lock_acquire: threads are busy-waiting on a spinlock that someone holds"],answer:3,why:"perf attributes 97.4% to spin_lock_acquire against 1.2% for the real work in cache_lookup. A spinlock keeps the thread on the CPU in a loop instead of sleeping, so contention shows up as 100% CPU with no progress. Fully busy CPUs with idle 0 and few switches are the signature."},{ask:"What is the likely root cause and fix?",options:["The CPUs are too slow: add cores","Use more threads so that someone gets the lock","The lock holder is not releasing (it was descheduled or is blocked while holding the spinlock, or an error path skipped the unlock); hold spinlocks only for very short non-blocking sections and use a sleeping mutex (futex) for anything longer","Raise the thread priority of the workers"],answer:2,why:"With four threads spinning, none are making progress, so the thread that owns the lock is not running its critical section: it blocked or was preempted while holding it, or never unlocked. Spinning wastes the CPU the holder needs. More cores or threads add more spinners, and a mutex lets waiters sleep so the holder can run and the CPU stays free."}],explain:"100% user CPU, a few context switches, no I/O wait and a profile dominated by a spin-lock function mean threads are busy-waiting on a lock that is not being released. Spin only for brief, non-blocking sections; otherwise use a sleeping lock.",move:h("Triage","sync",30)}];e.s(["f",0,d],94599);let c=[88761,71755,56483,46273,36291,29154,23254,18705,14949,11916,9548,7620,6100,4904,3906,3121,2501,1991,1586,1277,1024,820,655,526,423,335,272,215,172,137,110,87,70,56,45,36,29,23,18,15],p=(e,t,s)=>({name:e,type:t,power:s}),m=Math.round(1e3*(s=(t=[0,5].map(e=>{if(!Number.isInteger(e)||e<-20||e>19)throw Error("nice must be an integer in [-20, 19]");return c[e+20]})).reduce((e,t)=>e+t,0),t.map(e=>e/s))[0])/10,u=[{id:"tk-which-swap",prompt:"Latency spiked and you suspect the host is swapping and its tasks are blocked on I/O. Which one command shows si/so, the blocked count (b) and wa in one view?",options:["lsof -p PID","vmstat 1","ltrace -p PID","cat /proc/PID/maps"],answer:1,explain:"vmstat prints one line per interval: r and b (runnable and blocked tasks), swpd/free, si/so (swap in and out), bi/bo (block I/O), cs and the us/sy/id/wa CPU split. lsof lists open files, ltrace traces library calls and /proc/PID/maps shows one process's address space.",move:p("Vital Scan","io",34)},{id:"tk-which-disk",prompt:"vmstat shows wa at 80%. Which tool tells you which disk is saturated, with per-request latency (await) and %util?",options:["iostat -x 1","free -m","taskset -p PID","strace -c"],answer:0,explain:"iostat -x reports each block device separately: reads and writes per second, queue size, await (average time a request spends queued plus served) and %util. free only counts memory, taskset reads CPU affinity and strace -c counts system calls.",move:p("Disk Probe","io",34)},{id:"tk-which-syscalls",prompt:"A process is slow but not CPU-bound. Which command attaches to it and summarises which system calls it makes, how many and how long each takes?",options:["perf top","ps -eo state,pid,comm","ulimit -a","strace -c -p PID"],answer:3,explain:"strace -c counts every system call with time and errors, so a flood of futex or slow read calls stands out. perf top samples CPU functions instead, ps shows process states and ulimit -a prints the shell's resource limits.",move:p("Syscall Trace","io",36)},{id:"tk-which-hotfn",prompt:"A service pegs a core at 100% user time. Which tool samples the CPU and shows which functions burn the cycles?",options:["perf top","lsof","iostat","vmstat"],answer:0,explain:"perf top (or perf record then perf report) samples where the CPU is executing and ranks functions by their share, which finds a hot loop or a spin lock. vmstat and iostat only show that the CPU is busy, and lsof lists files.",move:p("Hot Spot","scheduler",36)},{id:"tk-fd-leak",kind:"multi",prompt:"You suspect a process leaks file descriptors. Which commands let you count or list its open descriptors? Pick all that apply.",options:["ls /proc/PID/fd | wc -l","lsof -p PID","vmstat 1","cat /proc/PID/limits"],answers:[0,1],explain:"/proc/PID/fd has one symlink per open descriptor, and lsof -p PID lists them with the file or socket each one points to. vmstat is system-wide and /proc/PID/limits shows the limit (Max open files) rather than how many are used.",move:p("Handle Count","io",34)},{id:"tk-proc-files",prompt:"Which /proc file shows a process's VmRSS, its thread count and its voluntary and involuntary context switches?",options:["/proc/PID/maps","/proc/PID/fd","/proc/PID/status","/proc/meminfo"],answer:2,explain:"/proc/PID/status is the human-readable summary: State, Threads, VmSize, VmRSS and voluntary_ctxt_switches / nonvoluntary_ctxt_switches. maps lists the mapped regions, fd the open descriptors and /proc/meminfo is system-wide.",move:p("Process Sheet","process",34)},{id:"tk-signals",kind:"multi",prompt:"Which of these signals can a process neither catch, block nor ignore? Pick all that apply.",options:["SIGKILL (9)","SIGTERM (15)","SIGSTOP (19)","SIGINT (2)"],answers:[0,2],explain:"SIGKILL and SIGSTOP are handled by the kernel itself so an administrator can always stop or kill a runaway process (on x86-64, SIGKILL is 9 and SIGSTOP is 19). SIGTERM (15) and SIGINT (2) can be handled, which is why you try SIGTERM first so the process can clean up.",move:p("Signal Cut","process",36)},{id:"tk-nice-share",kind:"numeric",prompt:"Two CPU-bound processes share one core under Linux's fair scheduler (CFS, and EEVDF since 6.6 use the same weights), one at nice 0 (weight 1024) and one at nice 5 (weight 335). What percentage of the CPU does the nice 0 process get?",answer:m,tolerance:.2,unit:"%",explain:"The fair scheduler gives each runnable task a share proportional to its weight: 1024 / (1024 + 335) = 75.4%. Each nice step changes the weight by about 1.25x, so five steps give roughly a 3:1 ratio. Nice only matters while tasks compete for the CPU.",move:p("Weighted Slice","scheduler",36)},{id:"tk-taskset",prompt:"`taskset 0x5 ./worker` runs a program with which CPU affinity?",options:["CPUs 0 and 5","CPU 5 only","CPUs 0 and 2","CPUs 1 and 3"],answer:2,explain:`The mask is a bit set with bit n meaning CPU n. 0x5 is binary 101, so bits 0 and 2 are set: CPUs ${(()=>{let e="0x5".replace(/^0x/,"");if(!/^[0-9a-f]+$/.test(e))throw Error("mask must be hexadecimal");let t=[];return[...e].reverse().forEach((e,s)=>{let a=parseInt(e,16);for(let e=0;e<4;e++)a&1<<e&&t.push(4*s+e)}),t})().join(" and ")}. The same affinity is written taskset -c 0,2.`,move:p("Core Pin","scheduler",34)},{id:"tk-ulimit",kind:"numeric",prompt:"A server runs with `ulimit -n 1024`. Descriptors are numbered from 0 (0, 1, 2 are stdin, stdout, stderr). What is the highest descriptor number it can ever hold?",answer:1023,tolerance:0,explain:"The limit is the number of descriptors, so numbers run 0 to 1023. The next open(), socket() or accept() fails with EMFILE (Too many open files). Raise the soft limit with ulimit -n or LimitNOFILE in systemd, but first make sure the process is not leaking.",move:p("Handle Cap","io",34)},{id:"tk-free-avail",prompt:"`free -m` shows 200 MB in the free column but 6 GB in available, with 6 GB in buff/cache. Is the machine short of memory?",options:["Yes: only 200 MB is free, so the OOM killer is close","No: available counts cache the kernel can drop, so about 6 GB can be handed to programs","Yes: cache cannot be reclaimed once it is used","No: available is swap that is still unused"],answer:1,explain:"Linux uses spare RAM as page cache, so free is usually small. available estimates what new programs can get without swapping: free memory plus the reclaimable part of the cache. Worry when available is small, not free.",move:p("Cache Read","memory",34)},{id:"tk-triage",kind:"order",prompt:"Put these steps of a first-pass triage of a slow Linux server in a sensible order.",steps:["uptime / top: look at load average and the CPU split","vmstat 1: is it swapping, or are tasks blocked on I/O?","iostat -x 1: which disk is saturated?","pidstat or ps: which process is responsible?","strace -p or perf top on that process: what is it doing?"],explain:"Work from the whole system down to a single process: load and CPU split first, then memory and I/O for the system, then the device, then the offending process, and last a system-call or CPU profile of that process. Each step narrows what the next tool needs to answer.",move:p("Triage Sweep","scheduler",38)}];function w(e,t){let s=e.map(()=>-1),a=[...e],o=0;for(;;){let e=!1;for(let i=0;i<a.length;i++){if(a[i]<=0)continue;e=!0,s[i]<0&&(s[i]=o);let r=null===t?a[i]:Math.min(t,a[i]);o+=r,a[i]-=r}if(!e)return s}}e.s(["f",0,u],30367);let f=(e,t,s)=>({name:e,type:t,power:s}),g=w([100,5,5],10)[2],y=w([100,5,5],null)[2],k={running:2,queued:3,rejected:3},v=[{id:"ds-lru-steps",kind:"order",prompt:"Design a thread-safe LRU cache. Put the design steps in a sensible order.",steps:["Pick the structure: a hash map for O(1) lookup plus a recency order (a doubly linked list)","get: find the entry and move it to the most-recently-used end","put: insert at the MRU end and, when over capacity, evict the LRU end","Protect the map and the list with one lock, since get also writes","Measure contention, then shard the cache by key hash if the lock is hot"],explain:"Choose the data structure first, then define each operation on it, then make it safe, then make it fast. The lock comes after the operations because only then do you know what they touch: a get reorders the list, so it is a write.",move:f("Cache Design","memory",38)},{id:"ds-lru-lock",prompt:"In your LRU cache, a teammate wants a readers-writer lock so many threads can run get() in parallel under the read lock. What goes wrong?",options:["Nothing: get never changes anything","get moves the entry to the MRU end, so concurrent gets corrupt the list","Readers would starve writers, but the data stays correct","The hash map cannot be read by two threads at once"],answer:1,explain:"In an LRU cache a get is a write: it reorders the recency list. Two gets under a shared read lock would relink the same nodes at once and can corrupt the list. Use one mutex (or shard the cache), or make the recency update approximate and lock-free.",move:f("Lock Audit","sync",36)},{id:"ds-rate-steps",kind:"order",prompt:"Design a rate limiter that allows 100 requests per second per client, with short bursts. Put the design steps in order.",steps:["Choose the algorithm: a token bucket per client (capacity = burst size, refill = 100 per second)","On each request, refill from the time elapsed since the last request, capped at capacity","If at least one token is left, take it and allow the request","Otherwise reject with 429 and a Retry-After hint","Keep the buckets in a map guarded by per-key locks or atomics, and expire idle ones"],explain:"Pick the algorithm, define the refill (done lazily from timestamps, so no timer thread per client), then the allow/reject decision, and last the concurrent bookkeeping. Refilling from elapsed time is what makes it cheap.",move:f("Throttle Plan","sync",38)},{id:"ds-rate-cap",prompt:"A token bucket forgets to cap the refill at its capacity. A client sends nothing for an hour, then floods. What happens?",options:["Requests are rejected for the first hour","Nothing: the limit still holds","The bucket has an hour of tokens, so a huge burst gets through","The refill thread crashes"],answer:2,explain:"Capacity is the maximum burst. Without the cap, idle time accumulates tokens without bound (3,600 s x the rate), and the first flood after a quiet hour is allowed in full. Capping at the capacity is what bounds the burst.",move:f("Burst Check","sync",34)},{id:"ds-pool-steps",kind:"order",prompt:"Design a thread pool with a bounded queue. Put the design steps in order.",steps:["Start a fixed number of worker threads, sized from the cores and the CPU/IO mix","Create a bounded blocking queue guarded by a mutex and two condition variables (not-empty, not-full)","Workers loop: wait while empty, pop a task, run it outside the lock","submit(): if the queue is full, apply a policy (block the caller, reject, or run it in the caller)","shutdown(): set a flag, wake every worker, let them drain the queue and join"],explain:"Workers and the queue come first, then the worker loop, then what submit does when full (the back-pressure policy), and shutdown last. Running the task outside the lock keeps the queue from being held while user code runs.",move:f("Pool Blueprint","process",38)},{id:"ds-pool-bound",prompt:`A pool has 2 workers. Eight tasks arrive at once. With a queue limited to 3, ${k.running} run, ${k.queued} wait and ${k.rejected} are rejected. Why is that better than an unbounded queue under a long overload?`,options:["It finishes every task sooner","It lets workers sleep less","It makes the tasks run in a different order","Overload turns into rejections the caller sees, instead of memory and latency growing without limit"],answer:3,explain:"An unbounded queue accepts everything, so during a sustained overload it grows until the process runs out of memory and every task waits longer. A bound turns the overload into explicit back-pressure: rejected, blocked or caller-runs, so clients can retry or slow down.",move:f("Back-pressure","io",36)},{id:"ds-sched-steps",kind:"order",prompt:"Design a user-space scheduler for green threads (cooperative tasks in one process). Put the design steps in order.",steps:["Give each task its own stack and a saved register context (makecontext / swapcontext or hand-written assembly)","Keep a run queue of ready tasks","yield(): save the current context, pick the next ready task, switch to it","Block and wake: parking a task on I/O or a lock removes it from the run queue until an event moves it back","Add preemption: a timer signal forces a yield so a CPU-bound task cannot hog the thread"],explain:"Contexts and stacks are the mechanism, the run queue is the policy's data, yield ties them together, blocking makes it useful for I/O, and preemption is the last refinement. Without a timer, a task that never yields owns the CPU.",move:f("Green Thread","scheduler",38)},{id:"ds-sched-preempt",prompt:`Tasks of 100, 5 and 5 time units are ready. Without preemption (run to completion) the third task first runs at t=${y}. With a 10-unit round-robin quantum it first runs at t=${g}. What does that show?`,options:["Round-robin makes the total work shorter","Preemption bounds how long a short task waits behind a long one","Round-robin always lowers turnaround for every task","Run to completion has better response time"],answer:1,explain:"Total work is unchanged. Preemption bounds how long any ready task waits for its first turn (here 15 instead of 105 units), which is response time. The cost is more context switches and a longer finish for the 100-unit task.",move:f("Quantum Check","scheduler",36)},{id:"ds-malloc-steps",kind:"order",prompt:"Design a simple malloc. Put the design steps in order.",steps:["Get memory from the OS: grow the heap with brk/sbrk (or mmap for large requests)","Give each block a header with its size and a free flag","malloc(n): walk the free list for a hole that fits (first or best fit) and split it if it is much larger","If nothing fits, ask the OS for more and add it to the list","free(p): mark the block free and coalesce it with free neighbours"],explain:"Source of memory, then the block metadata, then allocation with splitting, then the grow path, then free with coalescing. Splitting and coalescing are a pair: one carves holes, the other merges them back.",move:f("Heap Builder","memory",38)},{id:"ds-malloc-coalesce",prompt:"Your malloc never merges adjacent free blocks. A program allocates three adjacent 100-byte blocks, frees them all, then asks for 300 bytes in a 300-byte heap. What happens?",options:["It succeeds: the three holes are one 300-byte hole","It crashes in free()","It fails: three separate 100-byte holes remain, which is external fragmentation","It succeeds but is slower"],answer:2,explain:"Without coalescing the free list keeps three 100-byte holes and none fits a 300-byte request, even though 300 bytes are free. Merging adjacent free blocks on free() restores one 300-byte hole.",move:f("Fragment Check","memory",36)},{id:"ds-shell-steps",kind:"order",prompt:"Implement `ls | wc` in a shell. Put the system-call steps in order.",steps:["pipe(fds): create the pipe (read end fds[0], write end fds[1])","fork() the first child: dup2(fds[1], 1), close both pipe fds, exec ls","fork() the second child: dup2(fds[0], 0), close both pipe fds, exec wc","In the parent: close both pipe fds","In the parent: wait() for both children"],explain:"The pipe must exist before the forks so both children inherit it. Each child wires its end to stdin or stdout with dup2, then closes the originals. The parent closes its copies before waiting, otherwise a write end stays open and wc never sees end-of-file.",move:f("Pipe Fitter","process",38)},{id:"ds-shell-eof",prompt:"In your shell, `wc` never finishes after `ls` has exited. What is the most likely bug?",options:["ls wrote too much for the pipe","The pipe's write end is still open somewhere, for example the parent never closed it","wc was started before ls","dup2 copies the data instead of the descriptor"],answer:1,explain:"A reader gets end-of-file only when every write end is closed. After fork, the parent and both children each hold a copy, so if any copy stays open (typically the parent's), wc blocks in read() forever. Close the unused ends in every process.",move:f("Hang Hunt","process",36)},{id:"ds-chat-steps",kind:"order",prompt:"Design a chat server for thousands of clients on one thread, using file descriptors. Put the design steps in order.",steps:["Create a listening socket, set it non-blocking, and register it with epoll","Loop on epoll_wait: for each ready fd, handle only that fd","On the listening fd: accept() until EAGAIN and register each new client as non-blocking","On a client fd that is readable: read what is there, parse whole messages, queue them for the other clients' output buffers","On a writable client: write from its output buffer and drop EPOLLOUT interest once it is empty"],explain:"Everything is non-blocking so one slow client cannot stall the loop. epoll tells you which descriptors are ready, so cost follows activity, not connection count. Output goes through a per-client buffer because a non-blocking write can be short.",move:f("Chat Loop","io",38)},{id:"ds-chat-select",prompt:"The chat server is built on select() and grows to 5,000 clients. Which is the first hard limit it hits?",options:["select() cannot watch any descriptor numbered 1024 or higher (FD_SETSIZE)","TCP allows at most 1,024 connections","epoll is needed to read from sockets at all","Non-blocking sockets do not work with select()"],answer:0,explain:"select() uses a fixed-size bitmap, FD_SETSIZE, which is 1024 on Linux, so descriptors above 1023 cannot be watched (and it rescans the whole set on every call). poll has no such cap but still scans every entry; epoll removes both limits. The process also needs a higher ulimit -n for 5,000 sockets.",move:f("Scale Limit","io",36)}];e.s(["f",0,v],89470);var b=e.i(18646),x=e.i(42605);let T=(e,t,s)=>({name:e,type:t,power:s}),I=(0,b.I)(5e4,1e5,4,8),P=(0,b.g)(512,[{name:"worker",anonMB:300},{name:"sidecar",anonMB:250}],100),A=new Map([["/db/data",{data:"v1",sizeMB:100}],["/etc/motd",{data:"hi",sizeMB:1}]]),S=((a=new b.k([A])).write("/db/data","v2"),a.copiedUpMB),C=((o=new b.k([A])).remove("/etc/motd"),{seenByContainer:o.read("/etc/motd"),imageStillHas:void 0!==A.get("/etc/motd"),upperMB:o.upperMB}),_=(0,x.y)(16384,1200,1e3,64),R=[{id:"ct-cpu-throttle",kind:"numeric",prompt:'A container has cpu.max = "50000 100000" (50 ms of CPU per 100 ms period) and runs 4 busy threads on an 8-CPU host. For how many milliseconds of each period do the threads run before the cgroup is throttled?',answer:I.runUs/1e3,unit:"ms",explain:"The quota is CPU time summed over all CPUs. Four threads burn 4 ms of CPU per wall-clock ms, so 50 ms of quota is gone after 50 / 4 = 12.5 ms. The threads then sit throttled for the other 87.5 ms of the period, which is why a quota can cause latency spikes while average CPU use looks low.",move:T("Quota Wall","scheduler",36)},{id:"ct-throttle-latency",prompt:"A container's average CPU use is 30% of its limit, yet request latency spikes every few hundred milliseconds. cpu.stat shows nr_throttled climbing. What is the most likely cause?",options:["Bursts of threads use the whole quota early in a period, and the cgroup is throttled until the next period starts","The container shares the host kernel, so its system calls are slow","The page cache of the container is full","cpu.weight is set too high"],answer:0,explain:"cpu.max is enforced per period (100 ms by default), not on the average. A burst across many threads consumes the quota in a few milliseconds, and every runnable thread then waits for the period to roll over. Raise the quota, use fewer threads, or lengthen the period. cpu.weight only splits contended CPU; it never throttles.",move:T("Throttle Stall","scheduler",34)},{id:"ct-memory-max",prompt:"A cgroup has memory.max = 512 MB. Its processes hold worker 300 MB and sidecar 250 MB of anonymous memory, plus 100 MB of page cache. The cgroup reaches its limit. What does the kernel do?",options:["Drops the 100 MB of cache first; anonymous memory is still 550 MB, so the OOM killer shoots sidecar","Kills sidecar immediately and keeps the cache","Swaps the cache out and carries on","Drops the cache first; the OOM killer then kills the biggest process, worker"],answer:3,explain:`Page cache is reclaimable, so the kernel evicts it first (${P.reclaimedMB} MB here). The anonymous memory alone (550 MB) still exceeds the 512 MB limit, so the cgroup's OOM killer picks the process with the largest footprint: ${P.killed[0]}. The survivor then fits (${P.survivors[0].anonMB} MB).`,move:T("Cgroup Reaper","memory",36)},{id:"ct-copy-up",kind:"numeric",prompt:"A container's image has a 100 MB database file in a lower overlayfs layer. The container changes one byte of it. How many megabytes does overlayfs copy into the container's writable layer?",answer:S,unit:"MB",explain:"overlayfs works on whole files: the first write to a lower-layer file copies the entire file up to the upper layer (copy-up), however small the change. That is why databases belong on a volume, not in the image's writable layer.",move:T("Copy-Up","storage",34)},{id:"ct-whiteout",prompt:"Inside a container you run rm /etc/motd, a file that lives in a read-only image layer. What happens?",options:["The file is deleted from the image, so every container made from it loses the file","A whiteout entry is added to the writable layer; the container no longer sees the file and the image is unchanged","The command fails with EROFS","The file is copied up and then deleted, using 1 MB of the writable layer"],answer:1,explain:`Image layers are read-only and shared by all containers. Removing a lower-layer file records a whiteout (a special 0-byte node) in the upper layer, which hides the name from the merged view while the image keeps the file (here the container sees ${void 0===C.seenByContainer?"nothing":"a file"}, the image still has it: ${C.imageStillHas}, writable layer used: ${C.upperMB} MB).`,move:T("Whiteout","storage",32)},{id:"ct-pid1",prompt:"Your app runs as PID 1 in a container and has no SIGTERM handler. docker stop waits ten seconds and then SIGKILLs it. Why did SIGTERM not stop it?",options:["Containers cannot receive SIGTERM","SIGTERM is only delivered by a hypervisor","The first process of a PID namespace gets no default signal actions: a signal with no installed handler is ignored for PID 1","cgroups block signals to protect the limits"],answer:2,explain:"The kernel protects PID 1 of every PID namespace: a signal sent from inside the namespace is dropped unless PID 1 installed a handler (SIGKILL and SIGSTOP from an ancestor namespace still work, which is the eventual docker kill). Fix it by handling SIGTERM, or by running a tiny init such as tini (docker run --init), which also reaps orphaned zombies that would otherwise pile up under PID 1.",move:T("Init Guard","process",38)},{id:"ct-trap-emulate",prompt:"On classic x86 (before hardware virtualization support), POPF silently ignores the interrupt-flag bit instead of trapping when run in user mode. Why did that stop pure trap-and-emulate virtualization?",options:["POPF is too slow to emulate","It is sensitive but not privileged, so the deprivileged guest kernel runs it without a trap and the hypervisor never gets control","POPF needs 64-bit mode","It traps twice, which confuses the hypervisor"],answer:1,explain:"Popek and Goldberg: an architecture is classically virtualizable when every sensitive instruction is privileged, so each one traps to the hypervisor. POPF changes machine state (the interrupt flag) yet does not trap, so the guest's change is lost without a trace. VMware answered with binary translation, Xen with paravirtualization, and Intel VT-x / AMD-V with a guest mode that makes it exit.",move:T("Silent Flag","process",38)},{id:"ct-nested-walk",kind:"numeric",prompt:"With hardware nested paging (EPT/NPT), a guest uses 3-level page tables and the host's nested tables have 4 levels. On a TLB miss, how many memory references does the full two-dimensional walk need?",answer:(0,x.A)(3,4),unit:"refs",explain:"Each of the 3 guest-table reads and the final data address is a guest-physical address that needs its own 4-step nested walk, and the guest-table reads themselves cost 3 more: (3 + 1) × (4 + 1) − 1 = 19. This is why virtualized TLB misses are expensive and why huge pages matter even more in VMs.",move:T("Double Walk","memory",40)},{id:"ct-precopy",prompt:"A 16 GB VM is live-migrated over a 1000 MB/s link while the guest dirties memory at 1200 MB/s. Pre-copy migration will not converge, because each round re-sends more than the one before. What can the operator do?",options:["Add more RAM to the destination","Keep going; the last round always fits","Throttle the guest's CPU (auto-converge) or switch to post-copy, which moves execution first and fetches pages on demand","Shut the VM down for the length of one round"],answer:2,explain:`Pre-copy sends all memory, then the pages dirtied meanwhile, round after round, and pauses the guest only for a small remainder. When the dirty rate exceeds the link rate the remainder never shrinks (this run converges: ${_.converges}). Throttling the guest lowers the dirty rate; post-copy resumes on the destination at once and faults missing pages in over the network, trading a longer slowdown for a bounded migration.`,move:T("Live Move","io",38)},{id:"ct-numa-first-touch",prompt:"On a two-socket NUMA server, a program allocates a large array on one thread, but 32 worker threads on both sockets then read it. Linux's default first-touch policy puts each page on the node of the thread that first writes it. Why is the program slower than expected?",options:["Every page lands on the node where the allocating thread first wrote it, so threads on the other socket pay remote-memory latency and share one memory controller","NUMA machines have no shared memory","First-touch spreads pages evenly, so caches are cold","The array is stored in swap until the second socket reads it"],answer:0,explain:"If one thread initializes everything, all pages sit on its node. Threads on the other socket reach them across the interconnect (roughly 1.5-2x the latency) and all traffic queues at one memory controller. Let each worker first-touch its own slice, interleave with numactl --interleave, or pin threads with their data (taskset / numactl --cpunodebind).",move:T("Remote Hop","memory",36)}];e.s(["f",0,R],28023);let W=(e,t,s)=>({name:e,type:t,power:s}),O=[{id:"ml-sched-ext",prompt:"What is sched_ext (mainline since Linux 6.12)?",options:["A scheduling class whose policy is written as a BPF program loaded at run time, with the kernel falling back to the fair scheduler if that program misbehaves","A replacement for the EEVDF fair scheduler that is compiled in by default","A real-time class for hard deadlines","A user-space library that pins threads to CPUs"],answer:0,explain:"sched_ext lets you implement a scheduler as BPF code and swap it in without rebuilding the kernel, which makes scheduler experiments much cheaper. It is opt-in per task (a separate scheduling policy), and a watchdog ejects a BPF scheduler that stalls runnable tasks, returning them to the fair class. It extends EEVDF's world; it does not replace it. (As of October 2026.)",move:W("Pluggable Policy","scheduler",38)},{id:"ml-psi-meaning",prompt:"/proc/pressure/memory shows `some avg10=30.00`. What does that say?",options:["Over the last 10 seconds, at least one runnable task was stalled waiting for memory about 30% of the time","30% of RAM is free","30% of page faults needed disk I/O","The system swapped 30 pages per second"],answer:0,explain:"Pressure stall information (PSI, Linux 4.20) measures lost time, not usage. `some` is the share of time at least one task was stalled on the resource; `full` is the share of time all non-idle tasks were stalled at once, so the CPU did no useful work. Because it is time-based it flags a thrashing system long before free-memory numbers look alarming.",move:W("Pressure Gauge","memory",36)},{id:"ml-ebpf-verifier",prompt:"Why can an unprivileged-looking eBPF program be loaded into the kernel without being able to crash it?",options:["The kernel interprets it in a separate process","The verifier statically checks it before load: bounded execution, in-range memory access and only allowed helper calls","It runs only in user space","Every instruction is signed by the hardware"],answer:1,explain:"Before an eBPF program runs, the in-kernel verifier walks every path and rejects code that might loop without bound, read or write out of range, or call something not permitted for its program type. Accepted programs are then JIT-compiled to native code. (Loading still needs privileges such as CAP_BPF; the verifier is about safety, not permission.)",move:W("Verified Probe","process",36)},{id:"ml-mglru",prompt:"What did the multi-generational LRU (MGLRU, mainline since Linux 6.1) change about page reclaim?",options:["It removed swapping","It sorts pages into several age generations instead of only an active and an inactive list, to choose better victims at lower CPU cost","It made every page 2 MB","It reclaims only file pages"],answer:1,explain:"The classic two-list scheme (active/inactive) had to scan a lot to find cold pages. MGLRU tracks multiple generations by age and uses page-table access bits more efficiently, which cut reclaim CPU and bad evictions on large-memory machines. It is controlled via /sys/kernel/mm/lru_gen/enabled. The textbook LRU and clock ideas still describe the goal. (As of October 2026.)",move:W("Generation Sweep","memory",38)},{id:"ml-folio",prompt:"In modern Linux memory management, what is a folio?",options:["A page-table level between PMD and PUD","A swap slot","A handle for one or more physically contiguous pages managed as a single unit, so the page cache and reclaim need not guess whether they hold a head or tail page","A cgroup memory limit"],answer:2,explain:"Folios (introduced in Linux 5.16) make 'a power-of-two group of contiguous pages' a first-class type. Page cache, readahead and file systems are being converted to folios, which cuts per-page overhead for large I/O and allows large folios in the page cache. A single 4 KB page is just a folio of order 0.",move:W("Page Bundle","memory",34)},{id:"ml-thp-madvise",prompt:"A latency-sensitive database sees occasional multi-millisecond stalls. /sys/kernel/mm/transparent_hugepage/enabled is `always`. What is a common mitigation?",options:["Set it to `madvise` (or `never`) so only regions that ask for huge pages get them","Disable the TLB","Increase the page size to 1 GB for everything","Turn on swap"],answer:0,explain:"With `always`, the kernel tries to back anonymous memory with 2 MB pages, and allocating or compacting a contiguous 2 MB block (or khugepaged collapsing pages) can stall the application. `madvise` limits huge pages to regions that opt in with madvise(MADV_HUGEPAGE). Huge pages still help TLB reach for large heaps, so the choice is a trade-off to measure, not a rule. (As of October 2026.)",move:W("Huge Page Toggle","memory",36)}];e.s(["f",0,O],6625)},64825,e=>{e.s(["f",0,{basics:[{id:"basics-priv",prompt:"A user program tries to execute a privileged instruction. What happens?",options:["It runs normally","The CPU switches to kernel mode and runs it","The hardware traps to the OS","The CPU silently skips it"],answer:2,explain:"The CPU raises an exception (trap) and the OS handles it, usually by terminating the process. User code never gets kernel mode just by trying.",move:{name:"Trap Strike",type:"io",power:30}},{id:"basics-irq",prompt:"How does a keyboard tell the CPU that a key was pressed?",options:["A system call","A hardware interrupt","A page fault","A fork()"],answer:1,explain:"Devices raise hardware interrupts. The CPU saves its state and jumps through the interrupt vector to the device's handler in the kernel.",move:{name:"IRQ Jolt",type:"io",power:30}},{id:"basics-syscall",prompt:"What makes a system call different from an ordinary function call?",options:["It is always faster","It never returns","It runs on a separate CPU","It traps from user mode into kernel mode"],answer:3,explain:"A system call executes a trap instruction: the CPU switches to kernel mode and runs a kernel handler, then returns to user mode.",move:{name:"Syscall Surge",type:"io",power:32}},{id:"basics-micro",prompt:"Which kernel design runs file systems and drivers as user-space servers that talk by message passing?",options:["Microkernel","Monolithic kernel","Batch monitor","Boot loader"],answer:0,explain:"A microkernel keeps only the essentials (IPC, scheduling, basic memory) in kernel mode and moves services into user-space servers.",move:{name:"Micro Pulse",type:"io",power:32}},{id:"basics-linux",prompt:"Linux is usually classified as which kind of kernel?",options:["Microkernel","Exokernel","Monolithic, with loadable modules","No kernel: it is a shell"],answer:2,explain:"Linux runs drivers, file systems and networking in one kernel address space, but can load and unload modules at run time.",move:{name:"Module Slam",type:"io",power:34}},{id:"basics-boot",prompt:"What is the boot loader's job?",options:["Schedule user processes","Load the kernel into memory and start it","Format the disk","Handle page faults"],answer:1,explain:"Firmware (BIOS/UEFI) runs the boot loader, which loads the kernel image into memory and jumps to its entry point.",move:{name:"Bootstrap",type:"io",power:36}}],processes:[{id:"proc-ready",prompt:"A process in the READY state is waiting for…",options:["An I/O operation","Its parent to exit","The CPU","A disk interrupt"],answer:2,explain:"Ready means runnable: it has everything except the CPU and sits in the ready queue until the scheduler dispatches it.",move:{name:"Dispatch",type:"process",power:30}},{id:"proc-fork3",prompt:"fork(); fork(); fork(); — how many processes exist afterwards, counting the original?",options:["3","4","6","8"],answer:3,explain:"Every fork() doubles the processes that reach it: 1 → 2 → 4 → 8. In general n forks in a row give 2ⁿ processes.",move:{name:"Fork Bomb",type:"process",power:34}},{id:"proc-exec",prompt:"After a successful exec(), what happens to the calling process?",options:["Its memory image is replaced by the new program; the PID stays","A new child process is created","It gets a new PID","It exits and its parent runs the program"],answer:0,explain:"exec() loads a new program into the current process. Same PID, new code, data, heap and stack. It only returns if it fails.",move:{name:"Exec Swap",type:"process",power:32}},{id:"proc-threads",prompt:"Threads of the same process share which of these?",options:["Registers","Stack","Heap and global data","Program counter"],answer:2,explain:"Threads share the code, data, heap and open files. Each thread has its own registers, program counter and stack.",move:{name:"Thread Lash",type:"process",power:32}},{id:"proc-zombie",prompt:"A child has exited, but its parent hasn't called wait() yet. The child is…",options:["An orphan","A zombie","A daemon","The idle process"],answer:1,explain:"A zombie has finished but keeps its process-table entry (exit status) until the parent reaps it with wait(). An orphan is a child whose parent died first.",move:{name:"Reap",type:"process",power:34}},{id:"proc-shm",prompt:"Once set up, which IPC method is usually fastest for passing large data between processes?",options:["Message passing through the kernel","Signals","Pipes","Shared memory"],answer:3,explain:"With shared memory, processes read and write the same pages directly, with no system call per message. They must synchronize access themselves.",move:{name:"Shared Slam",type:"process",power:36}}],scheduling:[{id:"sched-fcfs",prompt:"Bursts P1=24, P2=3, P3=3 ms all arrive at 0 in that order. Average waiting time under FCFS?",options:["3 ms","17 ms","13 ms","27 ms"],answer:1,explain:"P1 waits 0, P2 waits 24, P3 waits 27: (0 + 24 + 27) / 3 = 17 ms. One long job first makes everyone wait (the convoy effect).",move:{name:"Convoy Crush",type:"scheduler",power:30}},{id:"sched-sjf",prompt:"Same jobs (P1=24, P2=3, P3=3 ms, all at 0) under SJF. Average waiting time?",options:["3 ms","6 ms","9 ms","17 ms"],answer:0,explain:"SJF runs P2, P3, P1: waits 0, 3 and 6, so (0 + 3 + 6) / 3 = 3 ms. SJF gives the minimum average waiting time.",move:{name:"Short Burst",type:"scheduler",power:32}},{id:"sched-turnaround",prompt:"Turnaround time is…",options:["Time from arrival until it first runs","Burst time minus waiting time","Completion time minus arrival time","Time spent in the ready queue"],answer:2,explain:"Turnaround = completion − arrival. Waiting = turnaround − burst. Response = first run − arrival.",move:{name:"Turnabout",type:"scheduler",power:32}},{id:"sched-starve",prompt:"Which algorithm can starve long jobs unless aging is added?",options:["FCFS","Round Robin","Fair-share","Shortest Job First"],answer:3,explain:"SJF (and priority scheduling) keeps picking short jobs, so a long one can wait forever. Aging slowly raises the priority of waiting jobs.",move:{name:"Aging Strike",type:"scheduler",power:34}},{id:"sched-rr-big",prompt:"In Round Robin, if the time quantum is larger than every burst, RR behaves like…",options:["FCFS","SJF","SRTF","Priority"],answer:0,explain:"No job is ever preempted, so they simply run in arrival order: FCFS. A tiny quantum instead means lots of context-switch overhead.",move:{name:"Timer Tick",type:"io",power:34}},{id:"sched-preempt",prompt:"Which of these schedulers is preemptive?",options:["FCFS","Shortest Remaining Time First","Non-preemptive SJF","Non-preemptive priority"],answer:1,explain:"SRTF is preemptive SJF: when a job arrives with less remaining time than the running one, it takes the CPU.",move:{name:"Preempt",type:"scheduler",power:36}}],sync:[{id:"sync-race",prompt:"Two threads run count++ on a shared counter with no lock. Why can an update be lost?",options:["The compiler deletes one increment","count++ is a load, add and store that can interleave","Threads cannot share variables","Caches never write back"],answer:1,explain:"Both threads can load the same old value, add 1 and store it, so one increment overwrites the other. That's a race condition.",move:{name:"Race Rush",type:"sync",power:30}},{id:"sync-cs-reqs",prompt:"Which is NOT a requirement of a critical-section solution?",options:["Mutual exclusion","Progress","Strict alternation","Bounded waiting"],answer:2,explain:"The three requirements are mutual exclusion, progress and bounded waiting. Strict alternation actually breaks progress when one side doesn't want in.",move:{name:"Guard Gate",type:"sync",power:32}},{id:"sync-counting",prompt:"A counting semaphore starts at 3. How many threads can pass wait() before one blocks?",options:["1","2","3","Unlimited"],answer:2,explain:"Each wait() takes one unit. After three, the value is 0 and the fourth caller blocks until someone calls signal().",move:{name:"Count Down",type:"sync",power:32}},{id:"sync-wait-zero",prompt:"A thread calls wait() (P) on a semaphore whose value is 0. What happens?",options:["It blocks until another thread calls signal()","wait() returns an error","The value becomes 1","The thread is killed"],answer:0,explain:"The caller can't take a unit, so it is put to sleep on the semaphore's queue until a signal() (V) wakes it.",move:{name:"Semaphore Snare",type:"sync",power:34}},{id:"sync-mutex-owner",prompt:"Who should unlock a mutex?",options:["Any thread","Only the kernel","Only the main thread","The thread that locked it"],answer:3,explain:"A mutex has an owner: the thread that locked it must unlock it. A semaphore has no owner, so any thread may signal it.",move:{name:"Lock Bite",type:"sync",power:34}},{id:"sync-peterson",prompt:"Peterson's algorithm solves the critical-section problem for…",options:["Any number of processes","Exactly two processes","Interrupt handlers only","Single-threaded programs"],answer:1,explain:"Peterson's uses a turn variable and two flags to give mutual exclusion, progress and bounded waiting for two processes (on hardware without reordering).",move:{name:"Turn Taker",type:"sync",power:36}}],deadlocks:[{id:"dl-coffman",prompt:"Which is NOT one of the four Coffman conditions for deadlock?",options:["Mutual exclusion","Hold and wait","Circular wait","Preemption"],answer:3,explain:"The four are mutual exclusion, hold and wait, NO preemption and circular wait. Allowing preemption is one way to prevent deadlock.",move:{name:"Claw Clamp",type:"sync",power:30}},{id:"dl-rag",prompt:"In a resource-allocation graph where every resource has ONE instance, a cycle means…",options:["A deadlock exists","A deadlock might exist","No deadlock","Only starvation"],answer:0,explain:"With single-instance resources a cycle is necessary and sufficient for deadlock. With multiple instances a cycle only means it is possible.",move:{name:"Cycle Snap",type:"sync",power:32}},{id:"dl-banker-kind",prompt:"The Banker's algorithm is a deadlock ____ technique.",options:["prevention","avoidance","detection","recovery"],answer:1,explain:"It avoids deadlock: before granting a request it checks that the resulting state is still safe, and makes the process wait otherwise.",move:{name:"Vault Guard",type:"sync",power:32}},{id:"dl-ordering",prompt:"Numbering resource types and always requesting them in increasing order breaks which condition?",options:["Mutual exclusion","Hold and wait","No preemption","Circular wait"],answer:3,explain:"If every process climbs the order, no process can hold a higher resource while waiting for a lower one, so no cycle can form.",move:{name:"Rank Order",type:"sync",power:34}},{id:"dl-safe-seq",prompt:"Available = 3. P0 holds 1 (max 4), P1 holds 2 (max 6), P2 holds 3 (max 5). Which is a safe sequence?",options:["P1, P0, P2","P1, P2, P0","P2, P0, P1","None: the state is unsafe"],answer:2,explain:"Needs are P0 3, P1 4, P2 2. P2 fits (3 ≥ 2) and frees 3 → 6; then P0 → 7; then P1. Starting with P1 fails: it needs 4 but only 3 are free.",move:{name:"Safe Passage",type:"sync",power:34}},{id:"dl-recovery",prompt:"Aborting one process in a deadlock cycle to free its resources is deadlock…",options:["prevention","avoidance","recovery","ignoring (the ostrich approach)"],answer:2,explain:"Detection finds the cycle; recovery breaks it by aborting processes or preempting resources (with rollback).",move:{name:"Rollback",type:"sync",power:36}}],memory:[{id:"mem-best-fit",prompt:"Free holes in order: 100K, 500K, 200K, 300K, 600K. Where does a 212K request go under BEST fit?",options:["500K","600K","300K","200K"],answer:2,explain:"Best fit picks the smallest hole that is big enough. 500K, 300K and 600K fit; 300K is the smallest, leaving an 88K hole.",move:{name:"Snug Fit",type:"memory",power:30}},{id:"mem-first-fit",prompt:"Same holes (100K, 500K, 200K, 300K, 600K). Where does 212K go under FIRST fit?",options:["100K","500K","300K","600K"],answer:1,explain:"First fit scans from the start and takes the first hole big enough: 100K is too small, 500K fits.",move:{name:"First Grab",type:"memory",power:32}},{id:"mem-page-offset",prompt:"Pages are 4 KB (4096 bytes). Logical address 13000 is in which page, at which offset?",options:["Page 3, offset 904","Page 3, offset 712","Page 2, offset 4808","Page 4, offset 712"],answer:1,explain:"Page = 13000 div 4096 = 3, offset = 13000 − 3 × 4096 = 712.",move:{name:"Frame Shift",type:"memory",power:32}},{id:"mem-ext-frag",prompt:"Paging eliminates which kind of fragmentation?",options:["Internal","Both internal and external","Neither","External"],answer:3,explain:"Any free frame can hold any page, so there are no unusable gaps between allocations. The last page of a process can still be part-empty (internal).",move:{name:"Defrag",type:"memory",power:34}},{id:"mem-eat",prompt:"TLB hit ratio 80%, memory access 100 ns, TLB time ignored. Effective access time?",options:["100 ns","120 ns","140 ns","200 ns"],answer:1,explain:"A hit costs one memory access (100 ns); a miss reads the page table first (200 ns). EAT = 0.8 × 100 + 0.2 × 200 = 120 ns.",move:{name:"TLB Strike",type:"memory",power:34}},{id:"mem-segments",prompt:"Segmentation divides a program into…",options:["Variable-size logical units such as code, stack and heap","Fixed-size pages","Disk blocks","Equal-size frames"],answer:0,explain:"Segments match the programmer's view: each has a base and a limit, and an address is (segment, offset). Their uneven sizes cause external fragmentation.",move:{name:"Segfault",type:"memory",power:36}}],virtual:[{id:"vm-fifo",prompt:"Reference string 7 0 1 2 0 3 0 4 2 3 0 3 2 1 2 0 1 7 0 1 with 3 frames, FIFO. How many page faults?",options:["9","12","15","20"],answer:2,explain:"FIFO evicts the page loaded earliest and faults 15 times on this string. LRU gives 12 and the optimal algorithm 9.",move:{name:"Queue Evict",type:"memory",power:30}},{id:"vm-lru",prompt:"Same string (7 0 1 2 0 3 0 4 2 3 0 3 2 1 2 0 1 7 0 1), 3 frames, LRU. How many page faults?",options:["15","12","9","10"],answer:1,explain:"LRU evicts the page unused for the longest time: 12 faults, between FIFO's 15 and the optimal 9.",move:{name:"Stale Swipe",type:"memory",power:32}},{id:"vm-belady",prompt:"Belady's anomaly (more frames, MORE faults) can happen with which algorithm?",options:["LRU","Optimal","FIFO","Every stack algorithm"],answer:2,explain:"FIFO can fault more with more frames (e.g. 1 2 3 4 1 2 5 1 2 3 4 5: 9 faults with 3 frames, 10 with 4). LRU and Optimal are stack algorithms and never do.",move:{name:"Anomaly",type:"memory",power:32}},{id:"vm-thrash",prompt:"A system is thrashing when…",options:["Too few processes are loaded","The TLB is too large","The disk is full","Processes spend more time paging than executing"],answer:3,explain:"When the frames given are smaller than the working sets, processes fault constantly, CPU use collapses and the disk queue fills.",move:{name:"Thrash Storm",type:"process",power:34}},{id:"vm-fault",prompt:"A page fault happens when a process touches a page that is…",options:["Not currently in physical memory","Read-only","Already in the TLB","Shared with another process"],answer:0,explain:"The page-table entry is marked invalid/not present, so the MMU traps to the OS, which loads the page from disk and restarts the instruction.",move:{name:"Fault Line",type:"memory",power:34}},{id:"vm-opt",prompt:"Which replacement policy is optimal but can't be implemented exactly?",options:["LRU","OPT: evict the page used farthest in the future","Clock (second chance)","FIFO"],answer:1,explain:"OPT needs to know future references, so it serves as the yardstick that real policies like LRU and Clock approximate.",move:{name:"Foresight",type:"memory",power:36}}],storage:[{id:"fs-inode",prompt:"Which of these does a Unix inode NOT store?",options:["File size","Pointers to the data blocks","Permissions and owner","The file's name"],answer:3,explain:"Names live in directory entries that map a name to an inode number. That's why one inode can have several names (hard links).",move:{name:"Inode Ink",type:"storage",power:30}},{id:"fs-raid1",prompt:"RAID 1 gets its redundancy from…",options:["Mirroring","Striping without parity","Distributed parity","Dual parity"],answer:0,explain:"RAID 1 writes every block to two disks. RAID 0 stripes with no redundancy, RAID 5 uses distributed parity and RAID 6 dual parity.",move:{name:"Mirror Image",type:"storage",power:32}},{id:"fs-raid5",prompt:"Which RAID level stripes blocks with parity spread across all the disks?",options:["RAID 0","RAID 1","RAID 4","RAID 5"],answer:3,explain:"RAID 5 rotates the parity block across disks, so no single parity disk becomes a bottleneck (RAID 4 keeps parity on one disk). It survives one disk failure.",move:{name:"Parity Wave",type:"storage",power:32}},{id:"fs-fcfs-disk",prompt:"Head at cylinder 53, queue 98, 183, 37, 122, 14, 124, 65, 67. Total head movement under FCFS?",options:["236","640","208","299"],answer:1,explain:"FCFS serves requests in order: 45 + 85 + 146 + 85 + 108 + 110 + 59 + 2 = 640 cylinders. SSTF needs only 236 on the same queue.",move:{name:"Seek Sweep",type:"storage",power:34}},{id:"fs-journal",prompt:"A journaling file system mainly protects against…",options:["Slow seeks","Running out of inodes","Inconsistency after a crash","Fragmentation"],answer:2,explain:"Metadata changes are written to a log first. After a crash the log is replayed (or incomplete entries discarded) instead of a full fsck scan.",move:{name:"Log Replay",type:"storage",power:34}},{id:"fs-sstf",prompt:"Same queue (98, 183, 37, 122, 14, 124, 65, 67), head at 53, SSTF. Total head movement?",options:["640","208","236","299"],answer:2,explain:"SSTF always serves the closest request: 65, 67, 37, 14, 98, 122, 124, 183 = 236 cylinders. It's fast but can starve far requests.",move:{name:"Nearest Nab",type:"storage",power:36}}],interview:[{id:"iv-thread",prompt:"Process vs thread: what do threads of one process have that separate processes don't?",options:["Separate heaps","A shared address space","Guaranteed parallelism","Their own PIDs and page tables"],answer:1,explain:"Threads share one address space (code, heap, globals, files), so they're cheaper to create and switch, but one bad write can corrupt them all.",move:{name:"Thread Needle",type:"process",power:32}},{id:"iv-cow",prompt:"Why doesn't fork() copy all of the parent's memory straight away?",options:["The child never uses memory","Memory is copied to swap instead","Copy-on-write: pages are shared read-only and copied on the first write","The child shares the parent's heap forever"],answer:2,explain:"Parent and child map the same frames read-only. A write faults, and only then does the kernel copy that one page. fork() + exec() rarely copies anything.",move:{name:"Copy on Write",type:"memory",power:32}},{id:"iv-mutex-sem",prompt:"A mutex vs a binary semaphore: what does the mutex add?",options:["Ownership: only the thread that locked it may unlock it","Counting above 1","Busy-waiting","Nothing, they're identical"],answer:0,explain:"A mutex is owned, which enables priority inheritance and error checks. A semaphore is a signalling counter any thread may post, e.g. to wake another thread.",move:{name:"Owner's Lock",type:"sync",power:34}},{id:"iv-malloc",prompt:"A big malloc() succeeds instantly, yet the first write to each page is slow. Why?",options:["malloc is buggy","The heap lives on disk","The TLB is full","Pages are mapped lazily; the first touch page-faults to get a frame"],answer:3,explain:"Large allocations reserve virtual address space (mmap). The kernel gives physical frames on demand, so each first touch is a minor page fault.",move:{name:"Lazy Alloc",type:"memory",power:34}},{id:"iv-epoll",prompt:"Why does epoll scale better than select() for 10,000 sockets?",options:["It uses more threads","It returns only the ready descriptors instead of rescanning every fd each call","It disables interrupts","It busy-polls the network card"],answer:1,explain:"select() copies and scans the whole fd set every call: O(n). epoll registers interest once and the kernel keeps a ready list, so each wait costs O(ready).",move:{name:"Event Storm",type:"io",power:36}},{id:"iv-ctx",prompt:"Besides saving and restoring registers, what makes context switches between processes costly?",options:["Cache and TLB contents are lost or flushed","The disk must spin up","The kernel recompiles the scheduler","All files are closed and reopened"],answer:0,explain:"A new address space means TLB entries (without ASIDs) and warm cache lines no longer help, so the new process starts with misses. Thread switches avoid the address-space change.",move:{name:"Context Crash",type:"scheduler",power:38}}]}])},11743,e=>{var t=e.i(21595);let s=(e,t,s)=>({name:e,type:t,power:s}),a=[{id:"ivx-vm",kind:"multi",prompt:"Which of these does virtual memory give a process? Pick all that apply.",options:["Its own address space, isolated from other processes","Programs bigger than physical RAM","A guarantee that it never page-faults","Per-page protection (read / write / execute)"],answers:[0,1,3],explain:"Each process sees a private address space that the MMU maps onto frames, so processes are isolated, programs can exceed RAM (pages live on disk until touched) and pages carry protection bits. Page faults are exactly how it works, so there is no guarantee against them.",move:s("Address Veil","memory",34)},{id:"ivx-pagefault",kind:"order",prompt:"Put the steps of handling a page fault for a valid, non-resident page in order.",steps:["The MMU traps to the kernel","The kernel checks the address is valid for the process","It finds a free frame (evicting a victim if none)","It reads the page from disk into the frame","It updates the page table and marks the page present","The faulting instruction restarts"],explain:"The fault is a trap. The kernel first checks the access is legal (otherwise the process gets SIGSEGV), then makes room, reads the page in, fixes the page table and restarts the instruction that faulted, which now succeeds.",move:s("Fault Handler","memory",38)},{id:"ivx-thrash",prompt:"A server's CPU use falls as more processes start, and the disk light stays on. What is happening and what is the fix?",options:["A deadlock; kill a process at random","Thrashing: processes spend more time paging than running, so reduce the degree of multiprogramming","Disk fragmentation; defragment the disk","A cache miss storm; add a bigger L1 cache"],answer:1,explain:"When the sum of the working sets exceeds RAM, every process keeps faulting on pages another needs, so the CPU idles waiting for the paging disk. A scheduler that adds processes when CPU use drops makes it worse. Fix it by suspending or swapping out processes (or adding RAM) until each working set fits.",move:s("Thrash Storm","memory",38)},{id:"ivx-deadlock",kind:"multi",prompt:"Which of these prevent deadlock by breaking one of the four Coffman conditions? Pick all that apply.",options:["Always take locks in one global order","Request every resource at once, or hold none while waiting","Allow the OS to preempt resources from a waiting process","Add more CPUs"],answers:[0,1,2],explain:"A global lock order breaks circular wait, requesting everything at once breaks hold-and-wait, and preemption breaks no-preemption. More CPUs change none of the four conditions (mutual exclusion, hold and wait, no preemption, circular wait).",move:s("Order Decree","sync",36)},{id:"ivx-pageseg",prompt:"Paging versus segmentation: which statement is right?",options:["Segmentation uses fixed-size units and has no external fragmentation","Paging is visible to the programmer, segmentation is not","Paging uses fixed-size pages, so it has no external fragmentation (only internal); segments vary in size and suffer external fragmentation","Both have only internal fragmentation"],answer:2,explain:"Pages are all one size, so any free frame fits any page; the waste is the unused tail of a process's last page. Segments match logical units (code, stack, heap) and vary in size, so free memory splinters into holes. Real systems often page within segments.",move:s("Frame Split","memory",34)},{id:"ivx-segv",prompt:"A C program dereferences a null pointer. How does the kernel end up killing it?",options:["The compiler inserts a check that calls abort()","The CPU halts until the user restarts it","Page 0 is unmapped, so the access page-faults; the kernel finds no valid mapping and sends the process SIGSEGV","malloc() notices and frees the process"],answer:2,explain:"Nothing in hardware knows about C pointers. Address 0 simply has no valid page-table entry, so the MMU traps; the fault handler sees the address lies in no mapped region and delivers SIGSEGV, whose default action is to terminate (and maybe dump core).",move:s("Null Strike","memory",36)},{id:"ivx-forks",kind:"numeric",prompt:"How many processes exist in total (including the original) after this program has run its three fork() calls?",code:"int main(void) {\n  fork();\n  fork();\n  fork();\n  return 0;\n}",answer:8,unit:"processes",explain:"Every fork() doubles the number of processes, because the parent and every earlier child each continue and create one more: 2 × 2 × 2 = 2³ = 8 (7 new children).",move:s("Fork Bloom","process",36)},{id:"ivx-zombie",prompt:"What is a zombie process, and how do you get rid of it?",options:["A process stuck in an infinite loop; kill -9 it","A process that has exited but whose parent hasn't called wait(), so its table entry lingers; the parent must wait() (or die, so init reaps it)","A process swapped to disk; swap it back in","A thread without a stack; free the stack"],answer:1,explain:"After exit() the kernel keeps a small entry (PID and exit status) until the parent collects it with wait()/waitpid(). A zombie uses no CPU or memory beyond that entry, and kill can't remove it because it is already dead. If the parent exits, init adopts and reaps the child.",move:s("Zombie Grasp","process",34)},{id:"ivx-spin",prompt:"When is a spinlock a better choice than a sleeping mutex?",options:["On a single CPU, for long critical sections","When the critical section is very short and the holder is running on another CPU","When threads must wait for I/O","Never; spinlocks are always slower"],answer:1,explain:"A sleeping mutex costs two context switches. If the lock will be released in a few nanoseconds by a thread on another CPU, spinning is cheaper. On one CPU the holder can't run while you spin, and for long waits spinning just burns cycles.",move:s("Spin Snare","sync",34)},{id:"ivx-inversion",prompt:"Priority inversion: low-priority L holds a lock that high-priority H needs, and a medium-priority M keeps preempting L. What is the standard fix?",options:["Priority inheritance: L temporarily runs at H's priority until it releases the lock","Lower H's priority to match L","Kill M","Let H spin on the lock"],answer:0,explain:"With inheritance, L is boosted to H's priority while it holds the lock, so M can't preempt it, L finishes its critical section and H runs. This is the bug that repeatedly reset the Mars Pathfinder lander, fixed by enabling inheritance.",move:s("Boost Bind","sync",36)},{id:"ivx-eat-fault",kind:"numeric",prompt:"Memory access takes 200 ns, and servicing a page fault takes 8 ms. What is the effective access time (in ns) when one access in 1,000 page-faults?",answer:8199.8,tolerance:.5,unit:"ns",explain:"EAT = (1 − p) × 200 + p × 8,000,000 with p = 0.001: 0.999 × 200 + 0.001 × 8,000,000 = 199.8 + 8,000 = 8,199.8 ns, about 41 times slower than a plain memory access. Even a tiny fault rate dominates, because the disk is so slow.",move:s("Fault Tax","memory",40)},{id:"ivx-eat-tlb",kind:"numeric",prompt:"A single-level page table, a TLB lookup of 10 ns, a memory access of 100 ns and a 90% TLB hit ratio. What is the effective access time (in ns)?",answer:120,unit:"ns",explain:"A hit costs 10 + 100 = 110 ns. A miss costs 10 + 100 (read the page-table entry) + 100 (read the data) = 210 ns. EAT = 0.9 × 110 + 0.1 × 210 = 99 + 21 = 120 ns.",move:s("Cache Cut","memory",38)},{id:"ivx-syscall",kind:"order",prompt:"Put what happens on a system call such as read() in order.",steps:["The program puts the call number and arguments in registers","A trap instruction switches the CPU to kernel mode","The kernel looks the number up in the system-call table","The handler does the work and stores the result","The kernel returns to user mode after the trap"],explain:"The wrapper in libc loads the system-call number and arguments, then executes a trap (syscall or int). The CPU enters kernel mode at a fixed entry point, the kernel dispatches through its system-call table, runs the handler, then returns to user mode with the result in a register.",move:s("Trap Gate","io",32)},{id:"ivx-mmap",prompt:"What does mmap() on a file do differently from read()?",options:["It reads the whole file into the heap at once","It maps the file's pages into the address space; pages are loaded by page faults from the page cache, with no extra copy into a user buffer","It locks the file for other processes","It writes the file to swap"],answer:1,explain:"With mmap the file's page-cache pages are mapped straight into your address space, so touching a page faults it in lazily and no read() copy into a user buffer is needed. Reads and writes become ordinary memory accesses, and several processes can share the same cached pages.",move:s("Map Weave","memory",34)},{id:"ivx-nonblock",prompt:"A non-blocking read() on a socket that has no data yet returns…",options:["After waiting until data arrives","Zero bytes, meaning end of file","-1 with errno set to EAGAIN (EWOULDBLOCK), straight away","A segmentation fault"],answer:2,explain:"A blocking read sleeps until data is ready; a non-blocking one returns at once with -1 and EAGAIN so the program can do something else, usually while an event loop (select, poll or epoll) tells it when the descriptor becomes readable. A return of 0 means the peer closed the connection.",move:s("Poll Probe","io",32)},{id:"ivx-stack-heap",prompt:"Where do a function's local variables live, and where does malloc'd memory come from?",options:["Both on the stack","Locals on the calling thread's stack; malloc memory from the heap (brk / mmap), shared by every thread of the process","Locals in the heap; malloc memory on the stack","Both in the page table"],answer:1,explain:"Each thread has its own stack, holding return addresses, arguments and locals; it is freed automatically on return. The heap is one region per process, managed by malloc and grown with brk or mmap, and lives until freed, which is why returning a pointer to a local is a bug.",move:s("Stack Slam","process",32)},{id:"ivx-semaphore",kind:"numeric",prompt:"A counting semaphore starts at 3. Five threads each call wait() and nobody calls signal(). How many threads are blocked?",answer:2,unit:"threads",explain:"Each wait() decrements the count and the caller proceeds while the count stays at or above 0. The first three waits take it from 3 to 0 and succeed; the fourth and fifth would go negative, so those two threads block until someone signals.",move:s("Count Gate","sync",34)},{id:"ivx-rr",kind:"numeric",prompt:"Round Robin with quantum 4. P1, P2 and P3 all arrive at time 0 with bursts of 24, 3 and 3. What is the average waiting time?",answer:5.67,unit:"ms",explain:"The order is P1 (0–4), P2 (4–7), P3 (7–10), then P1 alone to 30. P1 waits 10 − 4 = 6, P2 waits 4 and P3 waits 7, so the average is (6 + 4 + 7) / 3 = 17/3 ≈ 5.67 ms. (Silberschatz, section 5.3.4.)",move:s("Quantum Cut","scheduler",38)},{id:"ivx-lru",prompt:"Why do real kernels approximate LRU (with a clock hand and reference bits) instead of implementing it exactly?",options:["LRU suffers from Belady's anomaly","Exact LRU needs the page order updated on every memory reference, which is far too costly in hardware or software","LRU needs future knowledge of the references","LRU can't be used with a TLB"],answer:1,explain:"LRU needs a timestamp or ordered stack updated on every single access. The hardware sets one reference bit per page instead and the clock algorithm sweeps, giving a second chance to pages whose bit is set. (LRU is a stack algorithm and has no Belady anomaly; Optimal is what needs the future.)",move:s("Clock Sweep","memory",36)},{id:"ivx-ipc",kind:"multi",prompt:"Which of these are ways for two separate processes on one machine to communicate? Pick all that apply.",options:["A pipe","A shared-memory segment (shm_open / mmap)","A Unix domain socket","Reading a local variable on the other process's stack directly"],answers:[0,1,2],explain:"Pipes, shared memory and sockets are all standard IPC. Processes have separate address spaces, so one cannot simply read another's stack; the OS has to set up a channel (or share a region) deliberately.",move:s("Pipe Link","process",34)},{id:"ivx-oom",prompt:"Linux has promised more memory than it has and then runs out. What does it do?",options:["Reboots","The OOM killer picks a victim by its badness score (mostly memory use) and kills it to free memory","Blocks every allocation forever","Silently makes pages bigger"],answer:1,explain:"Linux overcommits by default: malloc succeeds because pages are only allocated on first touch. If real frames then run out and reclaim can't keep up, the out-of-memory killer chooses a process by oom_score (roughly its share of memory, adjustable with oom_score_adj) and sends it SIGKILL.",move:s("Reaper Call","memory",36)},{id:"ivx-dma",prompt:"What does DMA (direct memory access) save the CPU from?",options:["Ever handling an interrupt","Copying every byte of a transfer between the device and memory itself","Running the scheduler","Using virtual addresses"],answer:1,explain:"The CPU programs the DMA controller with a source, destination and length, and the controller moves the whole block over the bus while the CPU runs other work. The device raises one interrupt when the transfer completes, instead of one per byte (programmed I/O).",move:s("Bus Rush","io",34)},{id:"ivx-ptentries",kind:"numeric",prompt:"A 32-bit virtual address space with 4 KB pages and a single-level page table: how many page-table entries does each process need?",answer:1048576,tolerance:0,unit:"entries",explain:"4 KB = 2¹² bytes, so 12 bits are the offset and the other 20 bits are the page number: 2²⁰ = 1,048,576 entries. At 4 bytes each that is a 4 MB table per process, which is why systems use multi-level or inverted page tables.",move:s("Table Tally","memory",36)},{id:"ivx-links",prompt:"You create a hard link and a symbolic link to /data/report, then delete /data/report. What happens?",options:["Both links keep working, because links copy the file","Both links break, because the name was deleted","The symlink keeps working and the hard link breaks","The hard link keeps working (same inode, link count drops from 2 to 1); the symlink now dangles"],answer:3,explain:"A hard link is just another directory entry for the same inode, so the data survives until the link count reaches 0. A symlink stores a path, so once that path no longer resolves it dangles. Hard links also cannot cross file systems or (normally) point at directories; symlinks can.",move:s("Link Snap","storage",34)},{id:"ivx-journal",kind:"order",prompt:"Put the steps of a write-ahead (journaling) file-system update in order.",steps:["Write the transaction (the metadata changes) to the journal","Write a commit record to the journal","Checkpoint: write the changes to their final locations","Mark the transaction free in the journal"],explain:"The journal is made durable first, and only a committed transaction is trusted. After a crash, recovery replays committed transactions and ignores incomplete ones, so the file system never needs a full fsck scan. The journal space is freed only once the checkpoint is done.",move:s("Journal Seal","storage",36)},{id:"ivx-sjf",kind:"numeric",prompt:"Four jobs arrive together at time 0 with bursts 6, 8, 7 and 3 ms. Under non-preemptive SJF, what is the average waiting time?",answer:7,tolerance:0,unit:"ms",explain:"SJF runs 3, 6, 7, 8, so the waits are 0, 3, 9 and 16 ms: 28 / 4 = 7 ms (Silberschatz 5.3.2). FCFS in the given order would average 10.25 ms. SJF is optimal for average waiting time but needs the burst lengths in advance and can starve long jobs.",move:s("Shortest Slash","scheduler",36)},{id:"ivx-sstf",kind:"numeric",prompt:"The head is at cylinder 53 and the queue is 98, 183, 37, 122, 14, 124, 65, 67. How many cylinders does it move under SSTF?",answer:236,tolerance:0,unit:"cylinders",explain:"SSTF always serves the closest request: 65, 67, 37, 14, 98, 122, 124, 183, for 12 + 2 + 30 + 23 + 84 + 24 + 2 + 59 = 236 (Silberschatz 10.4.2). FCFS moves 640. SSTF can starve far-away requests, which is why SCAN-style policies exist.",move:s("Seek Dash","storage",36)},{id:"ivx-inode-blocks",kind:"numeric",prompt:"A Unix-style inode has 12 direct pointers and one single-indirect pointer. Blocks are 4 KB and pointers are 4 bytes. How many data blocks can a file have at most?",answer:1036,tolerance:0,unit:"blocks",explain:"An indirect block holds 4096 / 4 = 1024 pointers, so the file reaches 12 + 1024 = 1036 blocks (about 4 MB). Double- and triple-indirect pointers extend that to many GB, while small files need no indirect block at all.",move:s("Block Tally","storage",36)},{id:"ivx-banker-seq",prompt:"Silberschatz's Banker example has five processes, available (3, 3, 2) and these needs: P0 (7,4,3), P1 (1,2,2), P2 (6,0,0), P3 (0,1,1), P4 (4,3,1). Which order is a safe sequence?",options:["P0, P1, P2, P3, P4","P2, P0, P1, P3, P4","P4, P3, P2, P1, P0","P1, P3, P4, P0, P2"],answer:3,explain:"A sequence is safe if each process's need fits in what is free when its turn comes, and it then returns its allocation. P1 needs (1,2,2) <= (3,3,2); after it the free vector is (5,3,2), so P3 fits, then P4, P0 and P2. The other orders start with a process whose need exceeds (3,3,2) and so cannot run.",move:s("Safe Path","sync",38)},{id:"ivx-lock-order",prompt:"Thread 1 locks A then B; thread 2 locks B then A. They sometimes hang forever. What is the standard fix?",options:["Give both threads the same priority","Make every thread acquire locks in one global order (A before B)","Add a sleep() between the two lock calls","Use a spinlock instead of a mutex"],answer:1,explain:"The hang is a circular wait: each thread holds one lock and wants the other. Imposing a total order on locks removes circular wait, one of the four Coffman conditions, so deadlock is impossible. Sleeping only changes the timing, and priorities or spinlocks do not break the cycle.",move:s("Order Seal","sync",36)},{id:"ivx-coffman",kind:"multi",prompt:"Which of these four conditions must hold together for a deadlock to occur? Pick all that apply.",options:["Mutual exclusion","Hold and wait","Priority inversion","No preemption","Circular wait"],answers:[0,1,3,4],explain:"Coffman's conditions are mutual exclusion, hold and wait, no preemption and circular wait. Breaking any one prevents deadlock. Priority inversion is a scheduling problem where a low-priority holder delays a high-priority waiter; it is not required for deadlock.",move:s("Coffman Hex","sync",38)},{id:"ivx-prodcons",kind:"order",prompt:"Put the producer's steps in order for a bounded buffer protected by semaphores empty, full and a mutex.",steps:["wait(empty)","wait(mutex)","Add the item to the buffer","signal(mutex)","signal(full)"],explain:"The producer first waits for a free slot, then takes the mutex for the buffer update, and finally signals that an item is available. Swapping wait(empty) and wait(mutex) can deadlock: a producer holding the mutex while the buffer is full blocks the consumer that would free a slot.",move:s("Buffer Bind","sync",36)},{id:"ivx-rag",prompt:"In a resource-allocation graph where every resource has exactly one instance, you find a cycle. What does it mean?",options:["The processes are definitely deadlocked","The state is safe but tight","A deadlock is possible but not certain","Nothing; only a knot of three or more nodes matters"],answer:0,explain:"With single-instance resources a cycle is necessary and sufficient for deadlock: each process in it waits for a resource held by the next. With several instances per type a cycle only means deadlock is possible, and a detection algorithm like the Banker's safety check is needed.",move:s("Cycle Snare","sync",36)},{id:"ivx-belady",prompt:"FIFO page replacement on the reference string 1 2 3 4 1 2 5 1 2 3 4 5 gives 9 faults with 3 frames. What happens with 4 frames?",options:["Fewer faults, 7","Fewer faults, 8","The same, 9","More faults, 10"],answer:3,explain:"This is Belady's anomaly: FIFO takes 10 faults with 4 frames, one more than with 3. FIFO is not a stack algorithm, so a bigger memory does not always hold a superset of the pages. LRU and Optimal are stack algorithms and never behave this way.",move:s("Frame Twist","memory",38)},{id:"ivx-opt-faults",kind:"numeric",prompt:"Silberschatz's reference string is 7 0 1 2 0 3 0 4 2 3 0 3 2 1 2 0 1 7 0 1, with 3 frames. How many page faults does Optimal (Belady's MIN) take?",answer:9,explain:"Optimal always evicts the page whose next use is furthest away, which needs the future, so it is only a yardstick. It takes 9 faults here, against 12 for LRU and 15 for FIFO. (Silberschatz, section 10.4.)",move:s("Oracle Eye","memory",40)},{id:"ivx-internal-frag",kind:"numeric",prompt:"A process needs 72,766 bytes and the page size is 2,048 bytes. How many bytes of internal fragmentation does its last page waste?",answer:962,unit:"bytes",explain:"72,766 / 2,048 is 35 full pages plus 1,086 bytes, so the process takes 36 pages. The last page wastes 2,048 − 1,086 = 962 bytes. (Silberschatz, section 9.3.2.) On average a process wastes about half a page, which favours small pages, while a smaller page size makes the page table bigger.",move:s("Slack Crush","memory",36)},{id:"ivx-table-size",kind:"numeric",prompt:"A 32-bit address space, 4 KB pages and 4-byte page-table entries. How big is a flat single-level page table, in KB?",answer:4096,unit:"KB",explain:"32 − 12 offset bits leaves 20 page-number bits, so 2^20 entries of 4 bytes is 4 MB (4,096 KB) for every process. That is why systems use multi-level or hashed tables: most of a sparse address space needs no table at all.",move:s("Table Slam","memory",38)},{id:"ivx-first-fit",prompt:"Holes of 100, 500, 200, 300 and 600 KB (in that order) and requests of 212, 417, 112 and 426 KB. Which strategy places all four?",options:["First-fit","Worst-fit","Best-fit","None of them"],answer:2,explain:"First-fit puts 212 in the 500 hole, 417 in the 600 hole, 112 in the 288 left over, and then 426 has nowhere to go. Best-fit uses 300, 500, 200 and 600 exactly, so all four fit. Worst-fit also fails on 426. (Silberschatz, section 9.2.2.)",move:s("Gap Fill","memory",36)},{id:"ivx-look",kind:"numeric",prompt:"Request queue 98, 183, 37, 122, 14, 124, 65, 67 on a 200-cylinder disk, head at 53 moving toward cylinder 0. How many cylinders does LOOK move the head in total?",answer:208,unit:"cylinders",explain:"LOOK serves 37 and 14 on the way down (53 to 14 is 39 cylinders), then reverses at the last request in that direction and sweeps up to 183 (169 cylinders): 39 + 169 = 208. SCAN would run on to cylinder 0 first and move 236. (Silberschatz, section 11.2.)",move:s("Sweep Look","storage",36)},{id:"ivx-linked-reads",kind:"numeric",prompt:"A file uses linked allocation and only its directory entry (pointing at block 0) is in memory. How many disk reads does it take to read logical block 9 (the tenth block)?",answer:10,unit:"reads",explain:"Each block holds the pointer to the next, so reaching block 9 means reading blocks 0 through 9 in order: 10 reads. Contiguous allocation needs 1 and indexed allocation needs 2 (index block plus data block), which is why linked allocation is poor for random access. (Silberschatz, section 14.4.)",move:s("Chain Crawl","storage",34)},{id:"ivx-linked-data",kind:"numeric",prompt:"Linked allocation on 4,096-byte blocks, with 4 bytes of each block used for the pointer to the next block. How many bytes of file data does each block hold?",answer:4092,unit:"bytes",explain:"The pointer lives inside the block, so 4,096 − 4 = 4,092 bytes are left for data. Odd payload sizes like this are one cost of linked allocation; another is that a damaged pointer loses the rest of the file.",move:s("Pointer Tax","storage",32)},{id:"ivx-raid5",kind:"numeric",prompt:"Six 2 TB disks are set up as RAID 5. How many TB of usable space does the array provide?",answer:10,unit:"TB",explain:"RAID 5 stripes data with one disk's worth of distributed parity, so n − 1 = 5 disks hold data: 5 × 2 = 10 TB. It survives any single disk failure, rebuilding the lost disk from the XOR of the others. (Silberschatz, section 11.8.)",move:s("Parity Shield","storage",36)},{id:"ivx-raid-two",prompt:"Which RAID level is guaranteed to survive any two simultaneous disk failures?",options:["RAID 0","RAID 1 (a two-disk mirror)","RAID 5","RAID 6"],answer:3,explain:"RAID 6 keeps two independent parity blocks per stripe, so any two disks can be lost. RAID 5 and a two-way mirror survive one failure, and RAID 0 has no redundancy at all, so one failure destroys the array.",move:s("Double Parity","storage",36)},{id:"ivx-fork-prints",kind:"numeric",prompt:"How many lines does this program print in total, counting every process?",code:'int main(void) {\n  fork();\n  printf("hi\\n");\n  fork();\n  printf("hi\\n");\n  return 0;\n}',answer:6,unit:"lines",explain:"The first fork() makes 2 processes and both print (2 lines). The second fork() doubles that to 4 processes, and all 4 print (4 more lines): 2 + 4 = 6. Only the statements after a fork run in the child, so the child never repeats the first printf.",move:s("Echo Fork","process",36)},{id:"ivx-fork-child",kind:"numeric",prompt:"How many processes exist in total (including the original) after this program runs?",code:"int main(void) {\n  if (fork() == 0) {\n    fork();\n  }\n  return 0;\n}",answer:3,unit:"processes",explain:"fork() returns 0 only in the new child, so only the child runs the inner fork(). The parent never reaches it. That gives the original, its child, and the child's own child: 3 processes, not 4.",move:s("Branch Child","process",34)},{id:"ivx-wake-state",prompt:"A process blocked in read() on a disk file (WAITING) gets its data when the disk interrupt arrives. Which state does it move to?",options:["RUNNING, because the data it needs is ready","READY, because it must wait for the scheduler to dispatch it","NEW, because it restarts the system call","TERMINATED, because the I/O completed"],answer:1,explain:"I/O completion moves WAITING to READY. Only the scheduler's dispatch moves a process from READY to RUNNING, and another process may well hold the CPU at that moment. There is no WAITING to RUNNING arrow in the five-state diagram. (Silberschatz, section 3.1.2.)",move:s("Ready Wake","process",32)},{id:"ivx-exec",prompt:"What does a successful exec() call do?",options:["Creates a new child process running the given program","Replaces the calling process's code, data and stack with the new program, keeping the same PID","Runs the program in a new thread of the same process","Copies the parent's address space for the child"],answer:1,explain:"exec() loads a new program image over the calling process, so it only returns if it fails. The PID and open file descriptors survive. A shell starts a command by fork() to make a child, then exec() in the child to become the command, and wait() in the parent.",move:s("Image Swap","process",34)},{id:"ivx-ipc-fast",prompt:"Which IPC mechanism avoids copying each message through the kernel once it is set up?",options:["An ordinary pipe","A message queue","Shared memory","A signal"],answer:2,explain:"With shared memory the kernel maps the same physical pages into both processes, so after setup they read and write directly with no system call per message, which is why it is the fastest. The price is that the processes must synchronize themselves. Pipes and message queues copy every message through the kernel. (Silberschatz, section 3.5.)",move:s("Shared Slab","process",36)},{id:"ivx-inode-double",kind:"numeric",prompt:"An inode has 12 direct pointers, one single-indirect and one double-indirect pointer. Blocks are 4 KB and pointers are 4 bytes. What is the largest file, in blocks?",answer:1049612,unit:"blocks",explain:"A 4 KB block holds 4096 / 4 = 1024 pointers. Direct: 12. Single indirect: 1024. Double indirect: 1024 x 1024 = 1,048,576. Total 12 + 1024 + 1,048,576 = 1,049,612 blocks, a little over 4 GB.",move:s("Indirect Reach","storage",36)},{id:"ivx-indexed-reads",kind:"numeric",prompt:"With indexed allocation, only the directory entry is cached. How many disk reads fetch logical block 500 of a file (the file's index block fits in one block)?",answer:2,unit:"reads",explain:"One read for the index block, then one read for the data block it points to, no matter which block you want. Linked allocation would need 501 reads, while contiguous allocation needs just 1 but suffers external fragmentation.",move:s("Index Lookup","storage",32)},{id:"ivx-shared-offset",prompt:"A parent opens a file and calls fork(). The child reads 10 bytes, then the parent reads. Where does the parent's read start?",options:["At byte 0, because each process has its own offset","At byte 10, because the parent and child share one open file description and its offset","At the end of the file","It fails, because the descriptor was closed by fork()"],answer:1,explain:"fork() duplicates the descriptor table, but both entries point to the same open file description, which holds the file offset. A read by either process advances the shared offset, so the parent continues at byte 10. Opening the file again with open() would create an independent offset.",move:s("Shared Cursor","process",34)},{id:"ivx-unlink-open",prompt:"A process has a file open and another process runs unlink() on its only name. What happens to the data?",options:["It is erased at once and the next read fails","It stays until the last open descriptor is closed, then the inode and blocks are freed","It moves to lost+found","It stays forever until fsck runs"],answer:1,explain:"The inode keeps a link count and an open count. unlink() only removes the directory name and decrements the link count. The kernel frees the inode and its blocks when both counts are zero, so the process can keep reading and writing. This is a common way to make private temporary files.",move:s("Orphan Inode","storage",34)},{id:"ivx-write-durable",prompt:"write() on a regular file returns success. Is the data guaranteed to be on the disk?",options:["Yes, write() always waits for the device","No, it usually lands in the page cache, so call fsync() when you need durability","Only if the file is opened read-only","Only on SSDs"],answer:1,explain:"By default Linux copies the data into the page cache and writes it back later, which is faster. A crash or power loss before write-back can lose it. fsync() flushes the file's data and metadata to the device before it returns, and O_SYNC makes every write do that.",move:s("Cache Flush","storage",36)},{id:"ivx-rr-wait",kind:"numeric",prompt:"P1, P2 and P3 all arrive at time 0 with bursts of 24, 3 and 3 ms. Round Robin with a 4 ms quantum runs them in that order. What is the average waiting time, in ms (2 decimal places)?",answer:5.67,unit:"ms",explain:"Gantt: P1 0-4, P2 4-7, P3 7-10, then P1 10-30. P1 waits 10 - 4 = 6 ms, P2 waits 4 ms and P3 waits 7 ms. The average is 17 / 3 = 5.67 ms. FCFS on the same jobs would give 17 ms, the convoy effect. (Silberschatz, section 5.3.4.)",move:s("Time Slice","scheduler",36)},{id:"ivx-srtf-wait",kind:"numeric",prompt:"SRTF (preemptive SJF): P1 arrives at 0 with burst 8, P2 at 1 with burst 4, P3 at 2 with burst 9, P4 at 3 with burst 5. What is the average waiting time?",answer:6.5,unit:"ms",explain:"P1 runs 0-1, P2 preempts and runs 1-5, P4 runs 5-10, P1 finishes 10-17 and P3 runs 17-26. Waiting = completion - arrival - burst: P1 17 - 0 - 8 = 9, P2 5 - 1 - 4 = 0, P3 26 - 2 - 9 = 15, P4 10 - 3 - 5 = 2. The total is 26, so the average is 26 / 4 = 6.5 ms. (Silberschatz, section 5.3.2.)",move:s("Preempt Strike","scheduler",38)},{id:"ivx-convoy",prompt:"What is the convoy effect?",options:["Many short processes queue behind one long CPU-bound process, so average waiting time rises","Processes in a pipeline all share one address space","A burst of page faults after a context switch","Child processes inheriting the priority of their parent"],answer:0,explain:"In FCFS, one long CPU-bound job holds the CPU while short or I/O-bound jobs wait behind it, leaving devices idle and inflating the average wait. SJF or preemptive schemes like Round Robin avoid it. (Silberschatz, section 5.3.1.)",move:s("Slow Convoy","scheduler",32)},{id:"ivx-aging",prompt:"Under strict priority scheduling a low-priority process never runs because high-priority ones keep arriving. What is this called and what is the standard fix?",options:["Deadlock; kill a process","Starvation; aging, which gradually raises the priority of waiting processes","Thrashing; add more memory","Priority inversion; priority inheritance"],answer:1,explain:"Indefinite blocking by higher-priority work is starvation. Aging raises a process's priority the longer it waits, so it eventually runs. Priority inversion is different: a high-priority task waits on a lock held by a low-priority one.",move:s("Age Up","scheduler",34)},{id:"ivx-rr-quantum",prompt:"What happens to Round Robin as the time quantum grows towards infinity?",options:["It behaves like FCFS","It behaves like SJF","It starves long jobs","Context switches increase without bound"],answer:0,explain:"If the quantum exceeds every burst, each process finishes within its first turn, so the order is simply arrival order: FCFS. A tiny quantum goes the other way, with many context switches and mostly overhead. A good quantum is longer than most CPU bursts.",move:s("Long Slice","scheduler",32)},{id:"ivx-trap-vs-int",prompt:"What is the key difference between a trap (exception) and a hardware interrupt?",options:["A trap is synchronous, caused by the instruction being executed; an interrupt is asynchronous, raised by a device","A trap runs in user mode; an interrupt runs in kernel mode","A trap can be ignored; an interrupt cannot","A trap comes from a device; an interrupt comes from the program"],answer:0,explain:"A divide-by-zero, a page fault or the syscall instruction is caused by the instruction the CPU is running, so it is synchronous. A keyboard press, a finished disk read or the timer arrives from hardware at any moment, so it is asynchronous. Both switch to kernel mode and jump through the interrupt vector. (Silberschatz, chapter 1.)",move:s("Trap Door","process",32)},{id:"ivx-privileged",kind:"multi",prompt:"Which of these instructions must be privileged (kernel mode only)? Pick all that apply.",options:["Set the timer","Turn off interrupts","Add two registers","Load the page-table base register"],answers:[0,1,3],explain:"If a user program could set the timer, mask interrupts or change the page-table base, it could keep the CPU forever or read other processes' memory. Adding registers is harmless. Running a privileged instruction in user mode traps to the kernel.",move:s("Ring Zero","process",34)},{id:"ivx-syscall-trap",prompt:"Why does a system call use a trap instruction instead of an ordinary function call into the kernel?",options:["It switches to kernel mode and enters the kernel only at fixed, checked entry points","It is faster than a call because it skips the stack","It lets user code jump to any kernel address it likes","It copies the whole process into kernel memory"],answer:0,explain:"The trap raises the privilege level and jumps through a table the kernel set up, so a user program can only enter at defined entry points, never at an arbitrary kernel address. The kernel then validates the arguments before acting. A plain call would stay in user mode and could not touch protected state.",move:s("Syscall Gate","process",34)},{id:"ivx-boot-order",kind:"order",prompt:"Put the steps of booting a BIOS machine in order.",steps:t.O.BIOS.slice(),explain:"Firmware in ROM runs first and does the power-on self-test, then reads the boot block from disk. The boot loader (a bigger program) loads the kernel, the kernel sets up the hardware and root file system, and finally starts init, PID 1, the first user-mode process. (Silberschatz, section 2.10.)",move:s("Boot Chain","process",36)},{id:"ivx-microkernel",prompt:"What is the main trade-off of a microkernel compared with a monolithic kernel?",options:["Better isolation and reliability, but more message passing and context switches cost speed","Faster system calls, but drivers can crash the whole system","It needs no user-mode servers at all","It can only run on one CPU"],answer:0,explain:"A microkernel keeps only the minimum (address spaces, scheduling, IPC) in kernel mode and runs file systems and drivers as user-mode servers, so a driver crash does not take the system down. The price is extra IPC and mode switches for every service call. A monolithic kernel like Linux is faster but its drivers run with full privilege.",move:s("Tiny Core","process",32)},{id:"ivx-sem-count",prompt:"A counting semaphore starts at 2. Processes A, B and C each call wait() once, in that order, with no signal() yet. What is the semaphore's value, and who is blocked?",options:["Value -1; C is blocked","Value 0; nobody is blocked","Value -1; B and C are blocked","Value 2; nobody is blocked"],answer:0,explain:"Each wait() decrements: 2 -> 1 -> 0 -> -1. A and B got in while the value was positive; C's wait() made it negative, so C blocks. A negative value counts the waiting processes (here 1). The first signal() raises it to 0 and wakes C. (Silberschatz, section 6.6.2.)",move:s("Count Down","sync",32)},{id:"ivx-lost-update",kind:"numeric",prompt:"Two threads each run counter++ once on a shared counter that starts at 0. counter++ compiles to load, add, store. What is the smallest final value over all interleavings?",answer:1,explain:"If both threads load 0 before either stores, each computes 1 and stores 1, so one increment is lost and the result is 1. The largest possible value is 2, when the threads do not overlap. This is a race condition: the outcome depends on the interleaving. Protect the three steps with a lock or use an atomic add.",move:s("Lost Update","sync",34)},{id:"ivx-flag-first",prompt:"Each of two processes raises its own flag, then spins while the other's flag is up, then enters the critical section. What goes wrong?",options:["Both can raise their flags and then wait for each other forever","Both can enter the critical section together","Only one process can ever enter","Nothing; this is Peterson's algorithm"],answer:0,explain:"Mutual exclusion holds, but if both raise their flags before either checks, each sees the other's flag and spins forever: the progress requirement fails. Peterson's algorithm adds a turn variable so that exactly one of them yields. Checking the flag before raising your own breaks mutual exclusion instead.",move:s("Flag War","sync",34)},{id:"ivx-spinlock",prompt:"When is a spinlock a better choice than a blocking mutex?",options:["On a multiprocessor, when the lock is held only for a very short time","On a single CPU, when the lock is held for a long time","When the thread must sleep while holding the lock","Never; spinning always wastes the CPU"],answer:0,explain:"A spinning thread burns CPU cycles, but sleeping and waking costs two context switches. If the holder will release in less time than that, and it runs on another CPU, spinning is cheaper. On one CPU the holder cannot run while you spin, so spinning only wastes your time slice. (Silberschatz, section 6.5.)",move:s("Busy Wait","sync",32)},{id:"ivx-cv-while",prompt:"Why should a thread re-check its condition in a while loop around cond_wait() instead of using a single if?",options:["Another thread may have changed the state before this one runs again, and wakeups can be spurious","cond_wait() never releases the mutex","The loop makes the signal arrive faster","An if statement would deadlock the compiler"],answer:0,explain:"A woken thread must re-acquire the mutex, and by then another thread may have consumed the item or changed the state. POSIX also allows spurious wakeups. So the condition is re-tested in a loop: while (!ready) cond_wait(&cv, &m). cond_wait() atomically releases the mutex while sleeping and re-locks it on return.",move:s("Recheck","sync",32)},{id:"ivx-thread-shared",prompt:"Two threads of the same process run at once. Which of these does each thread have its own copy of?",options:["Its stack and register set","The heap","Global variables","The open file descriptor table"],answer:0,explain:"Threads of one process share the code, global data, heap and open files, which is why they communicate cheaply and why they need locks. Each thread needs its own stack (for its call frames and locals) and its own registers and program counter so it can run independently. (Silberschatz, section 4.1.)",move:s("Own Stack","process",32)},{id:"ivx-thread-switch",prompt:"Why is a context switch between two threads of the same process usually cheaper than one between two processes?",options:["The address space stays the same, so there is no page-table switch and the TLB need not be flushed","Threads never save their registers","Threads run in user mode only","The kernel skips the scheduler for threads"],answer:0,explain:"Both switches save and restore registers and the program counter. A process switch also changes the page table (and usually flushes or tags the TLB), so the next instructions run with cold translations and caches. Threads in one process keep the same address space, so only the register state changes.",move:s("Light Switch","process",32)},{id:"ivx-cow-fork",prompt:"A 2 GB process calls fork() and the child immediately calls exec(). Why is this fast on Linux?",options:["Copy-on-write: parent and child share the pages read-only and only copy a page when one of them writes it","fork() copies all 2 GB, but disks are fast","The child shares the parent's page table forever","exec() runs before fork() finishes"],answer:0,explain:"fork() duplicates the page tables and marks every page read-only and shared. A page is copied only on the first write (a protection fault), so the child that calls exec() almost never copies anything and its old address space is discarded. Without copy-on-write, fork-then-exec would copy 2 GB for nothing.",move:s("Lazy Copy","process",34)},{id:"ivx-fifo",prompt:"Two unrelated programs, started separately from different shells, must stream bytes one way and find each other by a path name. Which IPC fits?",options:["A named pipe (FIFO)","An ordinary (anonymous) pipe","A signal","Nothing; unrelated processes cannot communicate"],answer:0,explain:"A FIFO is created with mkfifo and has a name in the file system, so any process with permission can open it. An ordinary pipe has no name and is handed down through fork(), so it only reaches related processes. Signals carry no data.",move:s("Named Pipe","process",32)},{id:"ivx-sigint",prompt:"The user presses Ctrl-C in a terminal. Which mechanism tells the foreground program to stop?",options:["A signal (SIGINT)","Shared memory","A message queue","A named pipe"],answer:0,explain:"A signal is a small asynchronous notification delivered by the kernel; the terminal driver sends SIGINT to the foreground process group, and the default action terminates the program unless it installs a handler. Signals carry no payload, so they suit events, not data transfer.",move:s("Interrupt Bolt","process",30)},{id:"ivx-fifo-faults",kind:"numeric",prompt:"On Silberschatz's reference string 7 0 1 2 0 3 0 4 2 3 0 3 2 1 2 0 1 7 0 1 with 3 frames, how many page faults does FIFO take?",answer:15,explain:"FIFO evicts the page that has been resident longest, whether or not it is still being used, so it throws out hot pages such as 0. It takes 15 faults here, against 12 for LRU and 9 for Optimal. (Silberschatz, section 10.4.)",move:s("Queue Evict","memory",38)},{id:"ivx-page-size",prompt:"What is the trade-off when the OS picks a larger page size?",options:["A smaller page table and fewer TLB entries needed, but more internal fragmentation","A bigger page table but less internal fragmentation","No effect on either; page size only changes disk speed","Less internal fragmentation and fewer page faults, always"],answer:0,explain:"Doubling the page size halves the number of pages, so the page table shrinks and each TLB entry covers more memory. The cost is that the last page of every region wastes more space (about half a page on average), and each fault moves more data. Real systems also offer huge pages for big, dense regions.",move:s("Page Size","memory",32)},{id:"ivx-tlb-switch",prompt:"On a context switch to a different process, what must happen to a TLB that has no address-space identifiers (ASIDs)?",options:["It must be flushed, because its entries map the old process's pages","Nothing; virtual pages are the same in every process","Only the dirty entries are flushed","It is moved to disk and restored later"],answer:0,explain:"Page 5 of process A and page 5 of process B map to different frames. Without a process tag on each entry, the new process would hit stale translations and read the wrong memory, so the TLB is flushed and the new process starts with cold misses. With ASIDs, entries carry the owner and need no flush. Threads of one process share an address space, so they never need it.",move:s("TLB Flush","memory",34)},{id:"ivx-working-set",kind:"numeric",prompt:"A process references pages 1 2 1 3 2 1 2 4 5 4 5 4. With a working-set window of the last 4 references, how many pages are in its working set right after the 7th reference?",answer:3,explain:"The last four references up to and including the 7th are 3, 2, 1, 2, so the working set is {1, 2, 3}: three distinct pages. After the 12th reference the window holds 5, 4, 5, 4 and the set shrinks to {4, 5}. The OS keeps a process's working set resident; if the total demand exceeds the frames, the system thrashes.",move:s("Working Set","memory",36)},{id:"ivx-max-fault-rate",kind:"numeric",prompt:"Memory access takes 200 ns and servicing a page fault takes 8 ms. To slow the program by less than 10%, there can be at most one page fault per about how many memory accesses?",answer:399990,explain:"EAT = (1 − p) × 200 + p × 8,000,000 ns. A 10% slowdown means EAT ≤ 220 ns, so 200 + p × 7,999,800 ≤ 220 and p ≤ 20 / 7,999,800 ≈ 2.5 × 10⁻⁶. That is one fault per about 399,990 accesses. Page faults must be extremely rare for demand paging to work. (Silberschatz, section 10.2.1.)",move:s("Rare Fault","memory",40)},{id:"ivx-banker-request",prompt:"In Silberschatz's Banker example, P1 has just been granted (1,0,2), leaving (2,3,0) available. P0 now asks for (0,2,0), which is within its need and fits in what is free. What does the Banker's algorithm do?",options:["Grants it, because the request fits in the available vector","Refuses it for now: the resulting state would be unsafe, so P0 must wait","Kills P0 for exceeding its maximum claim","Grants it and then runs deadlock detection"],answer:1,explain:"Fitting in the free vector is necessary but not sufficient. The algorithm pretends to grant the request and runs the safety check: after it, available is (2,1,0) and no process's need fits, so the state is unsafe and P0 waits. An unsafe state is not yet a deadlock, but the Banker refuses to enter one. (Silberschatz, section 8.6.3.3.)",move:s("Safe Veto","sync",38)},{id:"ivx-min-resources",kind:"numeric",prompt:"Three processes each need at most 4 instances of one resource type, held until they finish. What is the smallest number of instances that makes deadlock impossible?",answer:10,tolerance:0,unit:"instances",explain:"The worst case gives every process one fewer than it needs: 3 × (4 − 1) = 9 instances, all held, with everyone stuck. One more instance lets some process finish and release, so n × (k − 1) + 1 = 10 instances guarantee no deadlock. With 9 the worst-case state is deadlocked.",move:s("Lean Pool","sync",36)},{id:"ivx-detect-count",kind:"numeric",prompt:"In Silberschatz's detection example (nothing free, no deadlock), P2 now requests one more instance of type C. How many processes are deadlocked?",answer:4,tolerance:0,unit:"processes",explain:"P0 holds resources but requests nothing, so it can finish and return (0,1,0), which satisfies no one else. P1, P2, P3 and P4 each wait for something another waiting process holds, so they can never finish: four processes are deadlocked. Detection is the Banker's safety loop run on requests instead of maximum needs. (Silberschatz, section 8.6.2.)",move:s("Cycle Scan","sync",40)},{id:"ivx-lock-ring",prompt:"Three threads lock two mutexes each, in this order: T1 takes A then B, T2 takes B then C, T3 takes C then A. Can the program deadlock?",options:["No: each thread holds only one mutex at a time","Yes: if each takes its first mutex before anyone takes a second, they wait in a ring","No: there are more mutexes than threads","Only if the threads have different priorities"],answer:1,explain:"If T1 holds A, T2 holds B and T3 holds C, then T1 wants B, T2 wants C and T3 wants A: a circular wait with no preemption. The fix is to give the mutexes a global order such as A < B < C and have every thread follow it; T3 would then take A first, and the ring cannot form.",move:s("Ring Lock","sync",36)},{id:"ivx-philosophers",prompt:"Five philosophers each pick up their left fork, then their right fork. What is a simple change that makes deadlock impossible?",options:["Make one philosopher pick up the right fork first","Make every philosopher wait one second before the second fork","Give each philosopher a priority","Add a sixth philosopher"],answer:0,explain:"If all five hold a left fork, each waits for the neighbour's fork in a circle. Reversing the order for one philosopher gives the forks a global order, which breaks circular wait. Waiting only changes the timing and can still livelock, priorities do not remove the cycle, and an extra philosopher adds another fork-hungry thread.",move:s("Fork Order","sync",36)},{id:"ivx-fcfs-turnaround",kind:"numeric",prompt:"P1, P2 and P3 arrive at time 0 with bursts of 24, 3 and 3 ms and run FCFS in that order. What is the average turnaround time, in ms?",answer:27,tolerance:0,unit:"ms",explain:"Completion times are 24, 27 and 30 ms, and every arrival is 0, so turnaround equals completion: (24 + 27 + 30) / 3 = 27 ms. Turnaround is completion minus arrival; waiting is turnaround minus burst, which gives the 17 ms average wait of the convoy effect. (Silberschatz, section 5.3.1.)",move:s("Turn Count","scheduler",34)},{id:"ivx-rr-response",kind:"numeric",prompt:"The same P1, P2 and P3 (bursts 24, 3 and 3 ms, all arriving at 0) run under Round Robin with a 4 ms quantum, in that order. What is the average response time, in ms (2 decimal places)?",answer:3.67,unit:"ms",explain:"Response time is the first time a process gets the CPU minus its arrival. P1 starts at 0, P2 at 4 and P3 at 7, so the average is (0 + 4 + 7) / 3 = 3.67 ms. FCFS would give (0 + 24 + 27) / 3 = 17 ms, which is why Round Robin suits interactive systems.",move:s("First Slice","scheduler",34)},{id:"ivx-sjf-optimal",prompt:"Which statement about Shortest-Job-First is true?",options:["It gives the minimum average waiting time for a given set of jobs, but it needs the next burst length, which can only be predicted","It is fair, because every process eventually gets the same share","It has the worst average waiting time of any algorithm","It cannot starve any process"],answer:0,explain:"Moving a short job ahead of a long one lowers the short job's wait by more than it raises the long job's, so SJF (and SRTF with arrivals) is optimal for average waiting time. The kernel cannot know the next CPU burst, so it estimates it, and long jobs can starve behind a stream of short ones.",move:s("Short First","scheduler",36)},{id:"ivx-tau-predict",kind:"numeric",prompt:"A scheduler predicts the next CPU burst with an exponential average, alpha = 1/2 and an initial guess of 10 ms. The measured bursts are 6, 4, 6, 4 and 13 ms. What is the prediction for the next burst, in ms?",answer:9,tolerance:0,unit:"ms",explain:"tau(n+1) = 0.5 * t(n) + 0.5 * tau(n). The predictions run 10, 8, 6, 6, 5, then 0.5 * 13 + 0.5 * 5 = 9 ms. Recent bursts count most, and each older burst's weight halves. (Silberschatz, figure 5.4.)",move:s("Burst Guess","scheduler",38)},{id:"ivx-ctx-overhead",kind:"numeric",prompt:"Round Robin uses a 10 ms quantum and each context switch costs 1 ms. If every process uses its full quantum, what percentage of CPU time does useful work (1 decimal place)?",answer:90.9,tolerance:.1,unit:"%",explain:"Each cycle is 10 ms of work plus 1 ms of switching, so useful time is 10 / 11 = 90.9%. Shrinking the quantum to 1 ms would drop it to 50%. Too large a quantum goes the other way and turns Round Robin into FCFS, so a quantum should exceed most CPU bursts. (Silberschatz, section 5.3.4.)",move:s("Switch Tax","scheduler",36)},{id:"ivx-fit-unplaced",kind:"numeric",prompt:"Free holes are 100K, 500K, 200K, 300K and 600K (in address order). Requests of 212K, 417K, 112K and 426K arrive in that order. Under first-fit, how many requests cannot be placed?",answer:1,tolerance:0,explain:"First-fit puts 212K in the 500K hole (288K left), 417K in the 600K hole (183K left) and 112K in the 288K remainder, so 426K finds no hole that large. Best-fit places all four (212K in 300K, 417K in 500K, 112K in 200K, 426K in 600K). (Silberschatz, exercise 9.x on contiguous allocation.)",move:s("Hole Hunter","memory",34)},{id:"ivx-outer-bits",kind:"numeric",prompt:"A 32-bit address space uses 4 KB pages and 4-byte entries, with each inner page table filling exactly one page. With a two-level page table, how many bits index the outer table?",answer:10,tolerance:0,unit:"bits",explain:"The 12-bit offset leaves a 20-bit page number. One page holds 4096 / 4 = 1024 entries, so the inner index takes 10 bits and the outer index takes the other 10: the 10 + 10 + 12 split. (Silberschatz, section 9.4.2.)",move:s("Table Split","memory",34)},{id:"ivx-pt-size",kind:"numeric",prompt:"A 32-bit system uses 4 KB pages and 4-byte page-table entries with a single-level page table. How large is one process's page table, in MB?",answer:4,tolerance:0,unit:"MB",explain:"A 4 KB page needs 12 offset bits, leaving 20 bits of page number, so the table has 2^20 entries. At 4 bytes each that is 4 MB per process, which is why multi-level and inverted page tables exist.",move:s("Table Flood","memory",36)},{id:"ivx-eat-98",kind:"numeric",prompt:"A TLB lookup takes 10 ns, a memory access takes 100 ns, the page table is single-level and the TLB hit ratio is 98%. What is the effective memory access time, in ns?",answer:112,tolerance:0,unit:"ns",explain:"A hit costs 10 + 100 = 110 ns. A miss costs 10 + 100 (page table) + 100 (the data) = 210 ns. So EAT = 0.98 * 110 + 0.02 * 210 = 107.8 + 4.2 = 112 ns, only 12% above a bare memory access.",move:s("Cache Hit","memory",36)},{id:"ivx-frag-kinds",prompt:"Which statement about fragmentation is correct?",options:["Paging has no external fragmentation but wastes part of each process's last page; contiguous allocation suffers external fragmentation, which compaction can reduce","Paging causes external fragmentation, and contiguous allocation causes internal fragmentation only","Compaction removes internal fragmentation inside pages","Best-fit is guaranteed to leave no external fragmentation"],answer:0,explain:"Any free frame fits any page, so paging cannot leave unusable holes between allocations, but the last page of each process is only partly used (internal fragmentation, always less than one page). Contiguous allocation leaves scattered holes, and compaction slides processes together to merge them.",move:s("Gap Sweep","memory",34)},{id:"ivx-fcfs-disk",kind:"numeric",prompt:"Request queue 98, 183, 37, 122, 14, 124, 65, 67 on a 200-cylinder disk, head at 53. How many cylinders does FCFS move the head in total?",answer:640,tolerance:0,unit:"cylinders",explain:"FCFS serves requests in arrival order: 53 to 98 (45), to 183 (85), to 37 (146), to 122 (85), to 14 (108), to 124 (110), to 65 (59), to 67 (2). The sum is 640 cylinders, the wild swings that SSTF (236) and the elevator algorithms avoid. (Silberschatz, section 11.2.)",move:s("Zigzag Arm","storage",34)},{id:"ivx-scan-disk",kind:"numeric",prompt:"Same queue (98, 183, 37, 122, 14, 124, 65, 67), head at 53 moving toward higher cylinders on a 200-cylinder disk (0 to 199). How many cylinders does SCAN move the head in total?",answer:331,tolerance:0,unit:"cylinders",explain:"SCAN sweeps up to the last cylinder, 199 (146 cylinders), serving 65, 67, 98, 122, 124 and 183 on the way, then reverses and sweeps down to 14, the lowest request (185 cylinders). 146 + 185 = 331. (Silberschatz, section 11.2.)",move:s("Elevator Sweep","storage",36)},{id:"ivx-cscan-disk",kind:"numeric",prompt:"Same queue and head at 53 moving up on a 200-cylinder disk. C-SCAN serves requests only while sweeping up, then jumps back to cylinder 0 and keeps going. Counting the return jump, how many cylinders does the head move in total?",answer:382,tolerance:0,unit:"cylinders",explain:"Up from 53 to 199 is 146 cylinders, the return jump 199 to 0 is 199, and then 0 up to 37 (the highest request below the start) is 37. 146 + 199 + 37 = 382. Without counting the jump it is 183. (Silberschatz, section 11.2.)",move:s("Circular Sweep","storage",36)},{id:"ivx-sstf-starve",prompt:"What is the main drawback of SSTF (shortest seek time first) disk scheduling?",options:["Requests far from the head can starve if closer requests keep arriving","It always moves the head more than FCFS","It needs the disk to be an SSD","It cannot serve requests behind the head"],answer:0,explain:"SSTF always picks the nearest pending request, so a steady stream of requests near the head can postpone a distant one indefinitely. It usually moves the head far less than FCFS (236 versus 640 cylinders on the textbook queue), which is why it is popular despite the unfairness. SCAN-style algorithms bound the wait.",move:s("Nearest Lure","storage",34)},{id:"ivx-cscan-why",prompt:"Why might a system choose C-SCAN over SCAN?",options:["It gives a more uniform wait time, because requests at both ends of the disk are reached after one full sweep","It moves the head fewer cylinders in every case","It never needs to reverse the head","It serves requests in arrival order"],answer:0,explain:"After SCAN reverses, cylinders just swept are served again soon while the far end waits about twice as long. C-SCAN treats the cylinders as a circular list: it serves in one direction only and returns to the start, so each cylinder waits roughly the same. It does not always move less (382 versus 331 on the textbook queue, counting the jump).",move:s("Ring Sweep","storage",34)},{id:"ivx-raid10-cap",kind:"numeric",prompt:"A RAID 10 array uses six 2 TB disks. How much usable capacity does it have?",answer:6,unit:"TB",explain:"RAID 10 stripes across mirrored pairs, so half the raw space holds copies. Six disks make three mirrored pairs, so 3 x 2 TB = 6 TB usable out of 12 TB raw. It survives one failure per pair, but two failures in the same pair lose the array.",move:s("Mirror Stripe","storage",34)},{id:"ivx-raid6-cap",kind:"numeric",prompt:"A RAID 6 array uses eight 1 TB disks. How much usable capacity does it have?",answer:6,unit:"TB",explain:"RAID 6 spends the equivalent of two disks on parity (two independent parity blocks per stripe, spread across all disks), so n - 2 = 6 disks' worth is usable: 6 TB out of 8 TB raw.",move:s("Double Parity","storage",36)},{id:"ivx-raid5-write",prompt:"Why is a small random write slow on RAID 5?",options:["It must read the old data and old parity, then write the new data and new parity (four I/Os)","Every write goes to all disks in the array","The parity disk must be rebuilt after each write","RAID 5 writes the data twice, as a mirror does"],answer:0,explain:"New parity = old parity XOR old data XOR new data, so updating one block needs two reads and two writes. This read-modify-write penalty is why write-heavy workloads often prefer RAID 10, which writes each block twice with no parity maths.",move:s("Parity Drag","storage",36)},{id:"ivx-inode-name",prompt:"In a Unix file system, where is a file's name stored?",options:["In the directory entry, which maps the name to an inode number","In the inode itself","In the file's first data block","In the superblock"],answer:0,explain:"A directory is a file of (name, inode number) pairs. The inode holds metadata (owner, permissions, size, timestamps, block pointers, link count) but no name, which is why one inode can have several names (hard links) and why rename is only a directory update.",move:s("Name Tag","storage",34)},{id:"ivx-contig-alloc",prompt:"What is the main drawback of contiguous file allocation?",options:["External fragmentation, and a file's size must be known or guessed so it can grow","Reading block n needs n disk reads","It needs an index block for every file","It cannot do sequential access"],answer:0,explain:"Contiguous allocation gives fast sequential and direct access (one seek, then the blocks follow), but free space breaks into holes and a file that outgrows its gap must be moved. Linked allocation needs n+1 reads to reach block n; indexed allocation needs an index block.",move:s("Gap Sweep","storage",34)},{id:"ivx-epoll-scale",prompt:"Why does epoll scale better than select() for thousands of mostly idle connections?",options:["The kernel keeps the interest set, so each wait costs time proportional to ready descriptors, not all watched ones","epoll copies the data into user space faster","select() cannot watch sockets","epoll uses one thread per connection"],answer:0,explain:"select() and poll() pass the whole descriptor set into the kernel on every call, and the kernel scans all of it: O(n) per call (select is also capped at FD_SETSIZE, usually 1024). epoll registers descriptors once with epoll_ctl, and epoll_wait returns only the ready ones, so the cost follows activity, not connection count.",move:s("Ready List","storage",36)},{id:"ivx-lowest-fd",kind:"numeric",prompt:"A fresh process has stdin, stdout and stderr open, and nothing else. It calls open() on a file. What file descriptor number does the call return?",answer:3,explain:"POSIX requires open() to return the lowest unused descriptor. 0, 1 and 2 are stdin, stdout and stderr, so the next is 3. Closing descriptor 1 first would make the next open() return 1, which is how shells redirect output with dup2.",move:s("Lowest Slot","storage",32)},{id:"ivx-hardlink-count",kind:"numeric",prompt:"A file has one name. You run ln to add two more hard links, then rm one of the three names. What is the inode's link count afterwards?",answer:2,explain:"A new file starts with link count 1; two ln commands raise it to 3; rm (unlink) removes one name and drops it to 2. The data is freed only when the count reaches 0 and no process still has the file open.",move:s("Link Count","storage",32)},{id:"ivx-sigkill",prompt:"Which statement about SIGKILL is correct?",options:["It cannot be caught, blocked or ignored, so the kernel always terminates the process","A handler registered with sigaction can clean up before it runs","It is the same as SIGTERM","It only works on child processes"],answer:0,explain:"SIGTERM is the polite request: a process can catch it and shut down cleanly. SIGKILL (and SIGSTOP) bypass the process entirely, which gives administrators a sure kill but no chance to flush files or release locks. A process in uninterruptible sleep (state D) dies only once its I/O completes.",move:s("Hard Stop","process",34)},{id:"ivx-pipe-full",prompt:"A process writes to a pipe whose buffer is full and the reader is slow. What happens by default?",options:["write() blocks until the reader drains space","write() fails and the data is dropped silently","The kernel grows the pipe without limit","The process receives SIGSEGV"],answer:0,explain:"A pipe has a bounded kernel buffer (64 KiB by default on Linux). A full pipe blocks the writer, which is natural back-pressure; with O_NONBLOCK the write returns -1 with EAGAIN instead. If the reader has closed its end, the write raises SIGPIPE or fails with EPIPE.",move:s("Full Pipe","process",34)},{id:"ivx-thread-stack",prompt:"Two threads of one process each call a function with a local variable x. Where does each thread's x live?",options:["On that thread's own stack, so the two copies are independent","In the shared heap, so both threads see one x","In the process's data segment","In the registers saved by the PCB, shared by both threads"],answer:0,explain:"Threads share the code, globals, heap and open files, but each has its own stack and register set (its own program counter). Locals and function arguments live on the thread's stack, so they need no lock; globals, heap objects and static variables are shared and do.",move:s("Own Stack","process",32)},{id:"ivx-dining-count",kind:"numeric",prompt:"Five philosophers sit at a round table with five forks, one between each pair. Each needs two forks to eat. What is the largest number who can eat at the same time?",answer:2,explain:"Each eater holds two forks, so k eaters need 2k forks and 2k <= 5 gives k <= 2. Two non-adjacent philosophers can eat together, and the fifth fork is left over but useless on its own.",move:s("Fork Pair","sync",32)},{id:"ivx-atomic-cas",prompt:"What does compare-and-swap (CAS) let you build without a lock?",options:["Lock-free updates: retry until the value is still the one you read, then swap it atomically","A guarantee that no other thread ever runs","Priority inheritance","Faster context switches"],answer:0,explain:"CAS(addr, expected, new) atomically writes new only if *addr still equals expected, and reports whether it did. A thread loops: read, compute, CAS, retry on failure. It never blocks others, but it can retry forever under contention and it is open to the ABA problem.",move:s("Swap Guard","sync",36)},{id:"ivx-priority-inversion",prompt:"A low-priority thread holds a lock that a high-priority thread needs, and a medium-priority thread keeps the CPU busy. What is this problem and its standard fix?",options:["Priority inversion; priority inheritance lets the lock holder run at the waiter's priority","Deadlock; always acquire locks in a fixed order","Starvation; add aging to the ready queue","A race condition; use a bigger quantum"],answer:0,explain:"The high-priority thread is blocked behind the low one, and the medium thread preempts the low one, so effectively the medium thread outranks the high one. With priority inheritance the holder is boosted until it releases the lock. This bug famously hit the Mars Pathfinder lander.",move:s("Boost Hand","scheduler",36)},{id:"ivx-notify-lost",prompt:"A thread calls cond_wait only after checking a flag, but another thread sets the flag and calls cond_signal between the check and the wait, without holding the mutex. What goes wrong?",options:["A lost wakeup: the signal arrives before anyone waits, so the waiter may sleep forever","A deadlock between two mutexes","The signal wakes every thread","Nothing; signals are queued until someone waits"],answer:0,explain:"Condition variables do not remember signals. Holding the mutex across the check and the wait (cond_wait releases it atomically as the thread sleeps) closes the gap, and the waiter should re-check the predicate in a while loop on waking.",move:s("Missed Call","sync",36)},{id:"ivx-lru-four",kind:"numeric",prompt:"On the reference string 7 0 1 2 0 3 0 4 2 3 0 3 2 1 2 0 1 7 0 1 with 4 frames, how many page faults does LRU take?",answer:8,explain:"The first four distinct pages (7, 0, 1, 2) fault, then 3, 4 and 1 each evict the least recently used page, and the final 7 faults again: 8 in total. With 3 frames the same string costs 12, so the extra frame saves four faults.",move:s("Recent Recall","storage",34)},{id:"ivx-fifo-four",kind:"numeric",prompt:"On the same reference string 7 0 1 2 0 3 0 4 2 3 0 3 2 1 2 0 1 7 0 1 with 4 frames, how many page faults does FIFO take?",answer:10,explain:"FIFO evicts by load order, not by use, so it throws out pages that are still hot and faults 10 times against LRU's 8. FIFO with 3 frames takes 15; this string does not trigger Belady's anomaly, but a different one can.",move:s("Queue Purge","storage",34)},{id:"ivx-vpn",kind:"numeric",prompt:"A system has 4 KB pages. What is the page number of virtual address 0x3A7F (decimal 14975)?",answer:3,explain:"4 KB pages mean a 12-bit offset, so the page number is the address shifted right by 12 bits: 0x3A7F >> 12 = 3, with offset 0xA7F. Equivalently 14975 div 4096 = 3 and 14975 mod 4096 = 2687.",move:s("Page Split","memory",32)},{id:"ivx-inverted-pt",prompt:"What is the defining property of an inverted page table?",options:["It has one entry per physical frame, so its size depends on RAM rather than on the virtual address space","It has one entry per virtual page of every process","It stores page tables on disk to save RAM","It removes the need for a TLB"],answer:0,explain:"An inverted page table maps frame number to (process id, page number), so its size is fixed by physical memory however many processes exist. The price is slower lookup, since you must search for the pair, which is usually done with a hash table, and a TLB is still used to make common accesses fast.",move:s("Frame Index","memory",36)},{id:"ivx-pure-demand",prompt:"In pure demand paging, how many of a process's pages are in memory when it first starts executing?",options:["None: even the first instruction page faults in","All of them","Only the stack","Only the pages marked dirty"],answer:0,explain:"Pure demand paging never loads a page until it is referenced, so the very first instruction fetch faults. Real systems soften this with prefetching or by mapping the executable lazily, but each page is still brought in on its first touch.",move:s("Lazy Load","memory",32)},{id:"ivx-mode-switch",prompt:"A user program calls read(). Which statement about the privilege change is correct?",options:["The trap instruction switches the CPU to kernel mode and jumps to a fixed kernel entry point; returning restores user mode","The program sets the mode bit itself before calling read()","The kernel is copied into the process's user address space first","The CPU stays in user mode and the kernel runs as a library"],answer:0,explain:"A system call executes a trap (syscall/svc/int) that raises privilege and vectors to a kernel-chosen address, so user code can never pick where kernel code starts. Changing the mode bit directly is itself a privileged operation, which is exactly why the trap exists.",move:s("Trap Door","process",32)},{id:"ivx-trap-vs-irq",prompt:"Which of these is an asynchronous interrupt rather than a synchronous trap or exception?",options:["A network card signalling that a packet has arrived","A divide-by-zero","A page fault on a load instruction","A system call instruction"],answer:0,explain:"Interrupts come from hardware devices at arbitrary times, independent of the instruction being executed. Divide-by-zero and page faults are exceptions raised by the running instruction, and a syscall is a deliberate software trap; all three are synchronous.",move:s("Device Ping","io",30)},{id:"ivx-lkm",prompt:"What does a loadable kernel module (such as a device driver) give a monolithic kernel like Linux?",options:["Code that can be added to or removed from the running kernel without rebooting, though it runs with full kernel privilege","A sandbox that isolates the driver in user mode","A separate address space for each driver","Immunity from crashes in driver code"],answer:0,explain:"Modules let a monolithic kernel stay extensible: a driver is linked into the kernel at run time. Because it runs in kernel mode in the kernel's address space, a bug in it can still crash the whole system, unlike a microkernel server in user space.",move:s("Hot Plug","process",34)},{id:"ivx-pid1",prompt:"What is special about the first user process (PID 1, init or systemd) that the kernel starts at the end of boot?",options:["It is the ancestor of all other user processes and adopts orphans, and the system halts or panics if it exits","It runs in kernel mode for its whole life","It is the only process allowed to call fork()","It owns all of physical memory"],answer:0,explain:"The kernel hand-crafts PID 1 and every other user process descends from it via fork. Orphaned children are re-parented to it so zombies get reaped, and since the system cannot run without it, the Linux kernel panics if it exits.",move:s("First Light","process",32)},{id:"ivx-dual-mode",prompt:"Why must instructions like halting the CPU or writing to an I/O port be privileged?",options:["So a buggy or malicious user program cannot take over the machine or bypass the OS's protection and resource control","Because they are too slow for user mode","Because user programs never need them","To reduce the size of the instruction set"],answer:0,explain:"Dual-mode operation lets hardware enforce that only the kernel can touch devices, the MMU and interrupt state. User programs get these services through system calls, where the kernel can check permissions first.",move:s("Ring Guard","process",30)},{id:"ivx-page-cache",prompt:"A process calls write() on a regular file and the call returns successfully. Where is the data most likely to be at that moment?",options:["In the kernel's page cache as a dirty page, to be flushed to disk later","Already on the disk platters","Only in the process's user-space buffer","In the CPU's TLB"],answer:0,explain:"Linux write() normally copies data into the page cache and marks it dirty; a background flusher writes it back later. That is why fsync() exists, and why a power cut can lose data from a write() that already returned.",move:s("Cache Slam","storage",32)},{id:"ivx-readahead",prompt:"Why does the kernel's read-ahead make sequential file reads faster?",options:["It prefetches the next blocks into the page cache, so later read() calls hit memory and the disk works in larger requests","It compresses the file","It skips the file system's directory lookup","It keeps the file in CPU registers"],answer:0,explain:"When the kernel detects sequential access it reads blocks ahead of the application. Later reads are page-cache hits, and disks are far more efficient with large sequential requests than with many small ones.",move:s("Look Ahead","storage",30)},{id:"ivx-dirty-flush",prompt:"What does fsync(fd) guarantee that a plain write(fd) does not?",options:["The file's dirty data (and needed metadata) has been sent to stable storage before the call returns","That the file is compressed","That no other process can read the file","That the file is cached forever"],answer:0,explain:"write() only promises the data reached the kernel. fsync() blocks until the data and the metadata required to find it are written to the device, which is what databases rely on for durability.",move:s("Flush Out","storage",32)},{id:"ivx-eat-disk",kind:"numeric",prompt:"Memory access takes 100 ns and a page-cache miss costs 10 ms (10,000,000 ns). With a 99% hit rate, what is the average access time in ns?",answer:100099,tolerance:0,unit:"ns",explain:"Average = 0.99 x 100 + 0.01 x 10,000,000 = 99 + 100,000 = 100,099 ns. Even 1% misses make the average 1000 times slower than a hit, which is why hit rate dominates cache design.",move:s("Hit Rate","memory",34)},{id:"ivx-buffered-vs-direct",prompt:"Why might a database open its files with O_DIRECT and bypass the page cache?",options:["It manages its own buffer pool and wants to avoid caching the same data twice and the kernel's write-back timing","O_DIRECT makes the disk faster than memory","The page cache cannot hold files larger than 1 GB","Only direct I/O can be read by other processes"],answer:0,explain:"A database already caches pages in its own buffer pool and needs precise control over when data reaches disk. Direct I/O avoids double buffering and kernel write-back policy, at the cost of losing the kernel's read-ahead and sharing.",move:s("Direct Hit","io",32)},{id:"ivx-container-vs-vm",prompt:"What is the key difference between a container and a virtual machine?",options:["Containers share the host kernel and are isolated by namespaces and cgroups; a VM runs its own guest kernel on virtual hardware","Containers run their own kernel; VMs share the host kernel","Containers need a hypervisor; VMs do not","There is no difference; they are two names for the same thing"],answer:0,explain:"A container is just isolated processes on the host kernel, so it starts fast and has little overhead. A VM boots a full guest OS on hardware emulated or partitioned by a hypervisor, giving stronger isolation at higher cost.",move:s("Sandbox Wall","process",32)},{id:"ivx-namespaces",prompt:"What do Linux namespaces provide to a container?",options:["Separate views of system resources such as PIDs, mounts, network interfaces and hostnames","Limits on how much CPU and memory a process may use","Encryption of the container's files","Faster system calls"],answer:0,explain:"Namespaces control what a process can see: its own PID 1, its own mount table, its own network stack. Limits on how much it can use are the job of cgroups.",move:s("Name Space","process",30)},{id:"ivx-cgroups",prompt:"Which Linux feature caps the CPU time and memory a container can consume?",options:["Control groups (cgroups)","Namespaces","chroot","Swap partitions"],answer:0,explain:"cgroups account for and limit resources (CPU shares, memory, I/O) per group of processes. A container that exceeds its memory cgroup limit is OOM-killed.",move:s("Quota Cap","scheduler",32)},{id:"ivx-type1-hypervisor",prompt:"What distinguishes a type 1 (bare-metal) hypervisor from a type 2 hypervisor?",options:["A type 1 hypervisor runs directly on the hardware; a type 2 runs as an application on a host OS","A type 1 hypervisor runs only containers","A type 2 hypervisor runs directly on the hardware","A type 1 hypervisor needs no CPU support"],answer:0,explain:"Type 1 hypervisors (Xen, KVM-based hosts, ESXi) sit on the hardware and schedule guests directly. Type 2 hypervisors (such as desktop virtualization apps) run on top of a normal host OS, adding a layer.",move:s("Bare Metal","process",34)},{id:"ivx-shadow-paging",prompt:"In a virtual machine, why does memory translation need an extra step?",options:["Guest virtual addresses map to guest physical addresses, which the hypervisor must map to real host physical addresses","The guest has no page tables","The TLB is disabled in guests","Guest memory is always swapped to disk"],answer:0,explain:"The guest OS believes its physical memory is real. The hypervisor adds a second mapping (shadow page tables, or hardware nested paging such as EPT/NPT) from guest-physical to host-physical addresses.",move:s("Nested Map","memory",34)},{id:"ivx-protection-rings",prompt:"How does hardware enforce that user programs cannot touch kernel memory or execute privileged instructions?",options:["The CPU has user and kernel modes; privileged instructions and kernel pages fault in user mode","The compiler removes dangerous instructions from user programs","The scheduler checks every instruction before it runs","Kernel memory is encrypted with the user's password"],answer:0,explain:"A mode bit (rings on x86) lets the CPU refuse privileged instructions in user mode, and page-table permission bits mark kernel pages supervisor-only. Violations raise a fault the kernel handles, usually by killing the process.",move:s("Ring Wall","memory",34)},{id:"ivx-nx-bit",prompt:"What does the NX (no-execute) page permission defend against?",options:["Injected code running from the stack or heap after a buffer overflow","Deadlock between two threads","Page faults on cold memory","Disk fragmentation"],answer:0,explain:"With NX, data pages such as the stack and heap are not executable, so shellcode an attacker writes there cannot run. Attackers answer with return-oriented programming, which reuses existing code.",move:s("No Exec","memory",32)},{id:"ivx-aslr",prompt:"What is the purpose of address space layout randomization (ASLR)?",options:["Randomizing where the stack, heap and libraries load, so an attacker cannot predict target addresses","Balancing page faults across processes","Spreading disk blocks evenly","Making the scheduler fair"],answer:0,explain:"Exploits often need exact addresses of code or data. ASLR changes them on each run, so a hard-coded address usually misses; information leaks can still defeat it.",move:s("Shuffle Map","memory",32)},{id:"ivx-least-privilege",prompt:"A web server must bind to port 80, which needs root. What does the principle of least privilege suggest?",options:["Start with the needed capability, then drop to an unprivileged user before handling requests","Run the whole server as root permanently","Make the server binary world-writable","Disable the user/kernel mode split"],answer:0,explain:"Least privilege means giving code only the rights it needs, for only as long as it needs them. Servers bind the low port, then call setuid to an unprivileged account so a compromise has limited reach.",move:s("Drop Rights","process",32)},{id:"ivx-acl-vs-capability",prompt:"How does an access control list differ from a capability list?",options:["An ACL is stored with each object and lists who may access it; a capability is held by a subject and names an object it may access","An ACL is stored with each subject; a capability is stored with each object","They are identical","ACLs apply only to memory; capabilities apply only to files"],answer:0,explain:"The access matrix can be stored by column (an ACL per object, as in Unix file permissions) or by row (a capability list per subject, like a file descriptor). ACLs make revoking an object's access easy; capabilities make delegation easy.",move:s("Access Matrix","storage",32)},{id:"ivx-boot-bios",prompt:"What is the bootloader's job in the boot sequence?",options:["Load the kernel image into memory and jump to it","Schedule user processes after login","Allocate page tables for each process","Mount network shares for the shell"],answer:0,explain:"Firmware (BIOS or UEFI) initializes hardware and finds the bootloader, which loads the kernel (and often an initial RAM disk) into memory and transfers control to it.",move:s("Cold Boot","process",30)},{id:"ivx-initramfs",prompt:"Why does Linux often boot with an initial RAM disk (initramfs)?",options:["It holds the drivers and tools needed to find and mount the real root file system","It stores swapped-out pages permanently","It replaces the page cache","It makes the kernel run faster than native code"],answer:0,explain:"The kernel cannot read the root file system until it has the right storage and file-system drivers. The initramfs is a small in-memory root that loads them, then switches to the real root.",move:s("Ram Disk","storage",30)},{id:"ivx-fork-bomb",prompt:"What is a fork bomb, and what limits the damage it can do?",options:["A process that forks copies of itself endlessly; per-user process limits (RLIMIT_NPROC or cgroup pids.max) cap it","A process that overwrites the bootloader; secure boot stops it","A thread that never releases a lock; the scheduler kills it","A page-fault loop that is stopped by the TLB"],answer:0,explain:"Each copy forks again, so the process count grows exponentially until the process table or memory is exhausted. A per-user process limit or a cgroup pids controller makes fork() fail once the cap is reached.",move:s("Fork Bomb","process",32)},{id:"ivx-orphan",prompt:"What happens to a running child whose parent exits first?",options:["It is adopted by init (PID 1), which reaps it when it exits","It is killed immediately","It becomes a zombie forever","It inherits the parent's priority and runs as the new parent"],answer:0,explain:"Orphans are re-parented to init (or a subreaper). Init calls wait() on its children, so the orphan does not stay a zombie after it finishes.",move:s("Adopt Child","process",32)},{id:"ivx-exec-fork",prompt:"In the Unix fork-then-exec pattern, what does exec() do?",options:["Replaces the calling process's memory image with a new program, keeping the same PID","Creates a new process with a new PID","Terminates the parent","Copies the file descriptor table to a sibling"],answer:0,explain:"fork() duplicates the process; exec() loads a new program into the current process, replacing code, data, heap and stack. The PID and usually open file descriptors stay, which is how shells set up redirection between the two calls.",move:s("Swap Image","process",32)},{id:"ivx-sigstop-cont",prompt:"What do SIGSTOP and SIGCONT do, and how does a shell use them for Ctrl+Z and fg?",options:["SIGSTOP suspends the process (it cannot be caught) and SIGCONT resumes it; job control sends them to the foreground group","SIGSTOP kills the process and SIGCONT restarts it from the beginning","SIGSTOP flushes the disk cache and SIGCONT remounts it","SIGSTOP blocks only the parent and SIGCONT unblocks the child"],answer:0,explain:"A stopped process stays in memory but is not scheduled until SIGCONT arrives. Ctrl+Z makes the terminal send SIGTSTP (a catchable stop) to the foreground process group, and fg or bg sends SIGCONT to resume it in the foreground or background.",move:s("Freeze Frame","process",32)},{id:"ivx-sigchld",prompt:"A parent forks many children but never calls wait(). What do you see in the process table as the children exit, and what signal is sent to the parent?",options:["Zombie entries that stay until reaped; SIGCHLD is sent to the parent","The children vanish immediately; SIGHUP is sent","The children become orphans; SIGKILL is sent","The children keep running; SIGALRM is sent"],answer:0,explain:"An exited child keeps its process-table entry (with its exit status) until the parent reaps it with wait() or waitpid(). The kernel sends SIGCHLD to the parent on each exit, and a handler that loops on waitpid() with WNOHANG is the standard way to reap them.",move:s("Reap Child","process",32)},{id:"ivx-sigpipe",prompt:"A process writes to a pipe whose read end has been closed by every reader. What happens by default?",options:["The write fails with EPIPE and the process receives SIGPIPE, which terminates it by default","The data is buffered forever","The write blocks until a reader reappears","The kernel reopens the read end automatically"],answer:0,explain:"Writing to a pipe with no readers is an error: the kernel raises SIGPIPE (default action: terminate) and write() returns EPIPE if the signal is ignored or caught. Conversely, reading from a pipe with no writers returns 0, i.e. end-of-file.",move:s("Broken Pipe","process",30)},{id:"ivx-signal-safe",prompt:"Why should a signal handler only call async-signal-safe functions such as write(), not printf() or malloc()?",options:["The handler can interrupt the program in the middle of printf or malloc, and re-entering them can corrupt their internal state or deadlock on their locks","Signal handlers run in a separate process with no libc","printf and malloc are privileged system calls","Handlers always run with interrupts disabled in kernel mode"],answer:0,explain:"A handler runs on the same thread at an arbitrary point. If the main code was inside malloc holding the heap lock, a handler that calls malloc will deadlock or corrupt the heap. POSIX lists the few async-signal-safe functions; the usual trick is to set a volatile sig_atomic_t flag and do the real work in the main loop.",move:s("Safe Handler","sync",32)},{id:"ivx-sigsegv",prompt:"What typically raises SIGSEGV when a program dereferences a bad pointer?",options:["The MMU faults on the invalid address, the kernel finds no valid mapping or permission, and sends SIGSEGV to the process","The compiler inserts a check that calls kill()","The disk controller reports a bad sector","The scheduler detects an infinite loop"],answer:0,explain:"The access traps into the kernel as a page fault. If the address is not in any mapped region (or the access violates its permissions), it is not a legitimate demand-paging fault, so the kernel delivers SIGSEGV; the default action terminates the process with a core dump.",move:s("Bad Pointer","memory",32)},{id:"ivx-polling-irq",prompt:"When is polling a device better than interrupt-driven I/O?",options:["When events are very frequent or the wait is shorter than an interrupt's overhead, e.g. a busy high-speed NIC","When the device is slow and idle most of the time","Never, because polling cannot read device registers","Only when DMA is disabled"],answer:0,explain:"An interrupt costs a mode switch, handler entry and cache disruption. If data arrives constantly (or the busy-wait is only a few cycles), checking a status register is cheaper; high-rate network stacks even switch from interrupts to polling under load. For rare events, interrupts avoid wasting CPU on empty polls.",move:s("Status Check","io",32)},{id:"ivx-top-bottom-half",prompt:"Why do Linux interrupt handlers split into a top half and a bottom half?",options:["The top half does the minimum with interrupts masked; the bottom half defers longer work so interrupts stay enabled and latency stays low","The top half runs in user mode and the bottom half in kernel mode","The top half handles reads and the bottom half handles writes","The bottom half runs before the top half to prepare the buffers"],answer:0,explain:"While a handler runs, its interrupt line is masked and latency for other events grows. The top half acknowledges the device and queues work; softirqs, tasklets or workqueues (the bottom half) finish the heavy processing later with interrupts enabled.",move:s("Deferred Work","io",32)},{id:"ivx-block-char",prompt:"What distinguishes a block device from a character device in Unix?",options:["A block device is accessed in fixed-size blocks with random access and buffering; a character device is a stream of bytes","A block device is always faster than a character device","A character device can only be written, never read","A block device cannot be mounted"],answer:0,explain:"Disks and SSDs are block devices: addressable blocks, cached by the page/buffer cache, and mountable with a file system. Terminals, serial ports and /dev/random are character devices that deliver bytes in order without random access.",move:s("Block Read","storage",30)},{id:"ivx-mmio",prompt:"What is memory-mapped I/O?",options:["Device registers appear in the address space, so ordinary load and store instructions control the device","Mapping a file into a process with mmap() so the page cache backs it","Copying device data into memory using DMA only","Swapping device drivers to disk"],answer:0,explain:"With MMIO the device's control and data registers occupy physical addresses, and the driver reads and writes them like memory (marked uncached). The alternative is port-mapped I/O, which uses special instructions such as in and out on x86.",move:s("Register Poke","io",32)},{id:"ivx-blocking-async",prompt:"How does non-blocking I/O differ from asynchronous I/O?",options:["Non-blocking returns immediately with 'would block' and you retry later; asynchronous starts the operation and notifies you when it has completed","They are the same thing","Non-blocking uses DMA and asynchronous uses polling","Asynchronous I/O blocks the whole process until the data arrives"],answer:0,explain:"With O_NONBLOCK, read() returns EAGAIN if no data is ready and the caller must try again (usually driven by select/epoll readiness). With asynchronous I/O (POSIX AIO, io_uring) the kernel performs the transfer and signals completion, so the data is already in your buffer.",move:s("Async Call","io",34)},{id:"ivx-amat",kind:"numeric",prompt:"A CPU cache has a 1 ns hit time, a 95% hit rate and a 100 ns penalty to fetch a line from main memory on a miss. What is the average memory access time (in ns)?",answer:6,unit:"ns",explain:"AMAT = hit time + miss rate × miss penalty = 1 + 0.05 × 100 = 6 ns. Even a 5% miss rate makes memory six times slower than the cache alone, which is why locality matters so much.",move:s("Cache Line","memory",36)},{id:"ivx-cache-tag",kind:"numeric",prompt:"A direct-mapped cache with 64-byte lines and 256 sets is addressed with 32-bit addresses. How many tag bits does each line store?",answer:18,unit:"bits",explain:"The offset takes log2(64) = 6 bits and the index takes log2(256) = 8 bits, so the tag is 32 - 6 - 8 = 18 bits. The index picks the set; the tag then identifies which block of memory is held there.",move:s("Tag Match","memory",36)},{id:"ivx-locality",prompt:"Which pair of access patterns shows spatial locality and temporal locality?",options:["Scanning an array in order (spatial); reusing a loop counter every iteration (temporal)","Reusing a loop counter (spatial); scanning an array in order (temporal)","Random pointer chasing (spatial); sorting a list (temporal)","Both terms mean the same thing"],answer:0,explain:"Spatial locality: after touching an address, nearby addresses are likely next, so a cache line fetched whole pays off. Temporal locality: an address touched recently is likely touched again soon, so keeping it cached pays off.",move:s("Prefetch","memory",32)},{id:"ivx-false-sharing",prompt:"What is false sharing?",options:["Threads on different cores write different variables that sit in the same cache line, so the line ping-pongs between cores","Two processes map the same file with mmap()","A thread reads a variable another thread has already freed","Two threads lock the same mutex"],answer:0,explain:"Coherence works per cache line, not per variable. Each write invalidates the other core's copy even though the data is logically independent, which slows both threads. Padding or aligning hot variables to separate lines fixes it.",move:s("Line Bounce","sync",34)},{id:"ivx-write-policy",prompt:"How does a write-back cache differ from a write-through cache?",options:["Write-back updates only the cache and marks the line dirty, writing memory when the line is evicted; write-through writes memory on every store","Write-back writes memory first and the cache later; write-through never writes memory","Write-through needs a dirty bit; write-back does not","They differ only in line size"],answer:0,explain:"Write-back saves memory bandwidth by combining many stores into one eviction write, but needs a dirty bit and more complex coherence. Write-through keeps memory always up to date at the cost of traffic, often hidden by a write buffer.",move:s("Dirty Bit","memory",34)},{id:"ivx-data-race",prompt:"What is the difference between a data race and a race condition?",options:["A data race is unsynchronized concurrent access to the same location where at least one access is a write; a race condition is any outcome that depends on timing, and can occur even with every access locked","They are two names for the same thing","A data race needs two processes; a race condition needs two threads","A race condition is always a hardware fault; a data race is always a software bug"],answer:0,explain:"Two threads that each lock a mutex around check and act separately (check balance, unlock, lock, withdraw) have no data race, yet still have a race condition because the result depends on interleaving. Conversely, some data races are benign. Fix races by making the whole check-then-act sequence atomic.",move:s("Race Surge","sync",34)},{id:"ivx-livelock",prompt:"How does livelock differ from deadlock?",options:["In livelock the threads keep running and changing state in response to each other but make no progress; in deadlock they are blocked and not running","Livelock happens only on single-core machines","Deadlock needs a spinlock; livelock needs a mutex","Livelock ends on its own after a timeout; deadlock does not"],answer:0,explain:"Two people stepping aside in a corridor in the same direction forever is livelock: both are active, neither advances. Two threads that each back off a lock and retry in lockstep behave the same way. Randomized backoff breaks the symmetry.",move:s("Endless Dance","sync",34)},{id:"ivx-aba",prompt:"What is the ABA problem in lock-free programming?",options:["A compare-and-swap succeeds because the value is A again, though it changed to B and back in between, so the structure may have changed under it","Two threads both read A and both write B","A thread acquires lock A then lock B while another does the reverse","A cache line moves between core A and core B repeatedly"],answer:0,explain:"CAS only compares values, not history. In a lock-free stack, a pop can read head A and next B, get preempted while others pop A, pop B and push A back, and then CAS head from A to B, linking to a freed node. Tagged (versioned) pointers or hazard pointers prevent it.",move:s("Swap Trick","sync",36)},{id:"ivx-reorder",prompt:"Thread 1 runs data = 42; ready = 1; and thread 2 spins until ready is 1 and then reads data, with plain variables and no fences. Why can thread 2 read a stale data value?",options:["The compiler or CPU may reorder or delay the stores, so ready can become visible before data","The kernel swaps thread 2 out before it reads data","Plain integer stores are not atomic on any hardware","Thread 2 reads from a different virtual address space"],answer:0,explain:"Without a memory barrier or release/acquire atomics, compilers and weakly ordered CPUs may reorder independent stores and loads, or buffer stores. Publishing with a release store on ready and an acquire load in the reader guarantees data is visible first.",move:s("Fence Wall","sync",36)},{id:"ivx-writer-starve",prompt:"A readers-writers lock always admits a new reader while other readers hold the lock. What can go wrong?",options:["A steady stream of readers can starve a waiting writer indefinitely","Readers can corrupt the data","Two writers can enter together","The lock deadlocks as soon as there are two readers"],answer:0,explain:"Reader-preference locks maximize concurrency but a writer may wait forever while overlapping readers keep arriving. Writer-preference or fair (FIFO) locks block new readers once a writer is waiting, trading some concurrency for bounded waiting.",move:s("Reader Flood","sync",34)},{id:"ivx-fsck-scan",prompt:"Why does a crash on a non-journaling file system force a slow fsck at boot, while a journaling one recovers quickly?",options:["Without a journal the system cannot know which updates were in flight, so fsck must scan all metadata for inconsistencies; with a journal only the recent log is replayed","fsck is needed only because the disk head crashed into the platter","Journaling file systems never lose any data, so no recovery is needed","Journaling copies the whole disk to RAM before every write"],answer:0,explain:"A multi-step update (allocate a block, update the inode, update the bitmap) can be cut short by a crash, leaving metadata inconsistent. fsck must walk every inode and bitmap to find out, which takes time proportional to disk size. A journal bounds the work to the transactions logged since the last checkpoint.",move:s("Scan Sweep","storage",34)},{id:"ivx-journal-meta",prompt:"Ext4's default ordered mode journals only metadata but writes file data blocks to disk before committing the metadata. Why that order?",options:["So that after a crash a committed inode never points at blocks holding stale or garbage data","Because data blocks are smaller than metadata","So the journal can be skipped entirely for data","To make writes faster than writing data after the commit"],answer:0,explain:"Metadata journaling keeps the file system structure consistent without writing every data block twice. Forcing data out before the commit means a new block pointer is only ever persisted after its contents are, avoiding exposure of old disk contents. Full data journaling is safer for the data itself but writes everything twice.",move:s("Ordered Seal","storage",36)},{id:"ivx-cow-fs",prompt:"How does a copy-on-write file system such as ZFS or Btrfs stay consistent without a journal?",options:["It never overwrites live blocks; it writes new blocks and then atomically switches the root pointer to the new tree","It keeps two full copies of the disk and compares them","It writes every block three times and votes","It disables caching so no update is ever partial"],answer:0,explain:"Because modified blocks and their parents are written to free space, the old tree stays intact until one root-pointer update commits the new one, so a crash leaves either the old or the new state. The same mechanism gives cheap snapshots, at the cost of fragmentation and extra write amplification.",move:s("Fresh Branch","storage",36)},{id:"ivx-inode-exhaust",prompt:'df shows 40% of the blocks free, yet creating a new file fails with "No space left on device". What is a likely cause?',options:["The file system has run out of inodes, for example from millions of tiny files","The disk is secretly full of free blocks","The page cache is out of memory","The file name is too short"],answer:0,explain:"Classic Unix file systems fix the inode count at mkfs time, and every file or directory needs one regardless of size. df -i shows inode usage. Fixes: delete or archive the small files, or recreate the file system with more inodes (or use one such as XFS or Btrfs that allocates them dynamically).",move:s("Inode Drain","storage",34)},{id:"ivx-atomic-rename",prompt:"How can a program replace a config file so a crash never leaves a half-written file?",options:["Write a temporary file in the same directory, fsync it, then rename() it over the original","Open the original with O_TRUNC and write the new contents in place","Delete the original first and then create the new one","Copy the file to /tmp and hope the system stays up"],answer:0,explain:"rename() within one file system is atomic: readers and a post-crash disk see either the complete old file or the complete new one. The fsync before the rename ensures the new contents are on disk first; syncing the directory afterward makes the rename itself durable. Truncating in place exposes an empty or partial file.",move:s("Swap Name","storage",34)},{id:"ivx-sendfile",prompt:"Why is sendfile() faster than a read()/write() loop for serving a static file over a socket?",options:["The kernel moves the data from the page cache to the socket without copying it through a user-space buffer, saving copies and system calls","It compresses the file before sending","It bypasses TCP entirely","It loads the whole file into the process's heap first"],answer:0,explain:"read()+write() copies file data from the page cache into a user buffer and back into a kernel socket buffer, with two system calls per chunk. sendfile() keeps the transfer inside the kernel (and with DMA gather can avoid the CPU copy altogether), so it uses less CPU and memory bandwidth. This is the classic zero-copy optimization.",move:s("Direct Route","io",34)},{id:"ivx-listen-backlog",prompt:"What does the backlog argument of listen() control?",options:["How many connections the kernel will queue for accept() while the server is busy; beyond that, new connection attempts may be dropped or refused","The maximum number of bytes per connection","How many threads the server may create","The number of clients that can be connected at the same time in total"],answer:0,explain:"The kernel completes TCP handshakes on the server's behalf and holds finished connections in an accept queue until the application calls accept(). The backlog bounds that queue, so a slow accept loop under a burst makes clients see timeouts or resets. It does not limit established connections, which are bounded by file descriptors and memory.",move:s("Queue Wall","io",34)},{id:"ivx-send-block",prompt:"A blocking send() on a TCP socket stalls because the peer reads slowly. What is happening inside the kernel?",options:["The socket send buffer is full because the peer's receive window is small, so send() sleeps until acknowledged data frees space","The CPU is too slow to run send()","The file descriptor table is full","The kernel dropped the connection"],answer:0,explain:"Data is copied into the kernel's per-socket send buffer and transmitted as the receiver's advertised window allows. A slow reader shrinks the window, ACKs free buffer space slowly, and a full buffer blocks send() (or returns EAGAIN if non-blocking). This is TCP flow control propagating back-pressure to the application.",move:s("Window Stall","io",36)},{id:"ivx-reuseaddr",prompt:'A server is restarted and bind() fails with "Address already in use" although the old process is gone. What is the usual fix?',options:["Set SO_REUSEADDR before bind(), because old connections in TIME_WAIT still hold the port","Reboot the machine every time","Use a smaller backlog","Call fork() before bind()"],answer:0,explain:"After a side closes a TCP connection actively, its socket lingers in TIME_WAIT (typically about 60 s on Linux) to absorb stray late segments. That socket still occupies the local address, so a plain bind() collides. SO_REUSEADDR lets a new listener bind while only such lingering connections exist.",move:s("Port Reclaim","io",34)},{id:"ivx-epoll-edge",prompt:"With edge-triggered epoll (EPOLLET), what must a handler do when a socket becomes readable?",options:["Read until read() returns EAGAIN, because a notification fires only on a new arrival, not while data is still unread","Read exactly one byte, as the event repeats until the socket is empty","Nothing; the kernel reads the data automatically","Close the socket to reset the event"],answer:0,explain:"Level-triggered epoll reports a descriptor as long as it is ready, so partial reads are safe. Edge-triggered epoll reports only the transition to ready; if the handler leaves data in the buffer, no further event may arrive and the connection stalls. Edge-triggered sockets must therefore be non-blocking and drained until EAGAIN.",move:s("Edge Drain","io",36)},{id:"ivx-nice",prompt:"On Linux, a process's nice value is raised from 0 to 10. What is the effect?",options:["It lowers the process's scheduling priority, so it gets a smaller share of CPU when others compete","It raises its priority so it runs first","It pins the process to one CPU core","It sets a hard 10 ms time limit"],answer:0,explain:"Nice values run from -20 (most favored) to +19 (least). A higher value makes the process 'nicer' to others: its weight shrinks (the same nice-to-weight table is used by CFS and by EEVDF, the fair scheduler since Linux 6.6), so it receives a smaller share of CPU time when there is contention. It does not grant exclusive use, and on an idle machine the process still runs at full speed. Raising priority (a negative nice) needs privilege.",move:s("Nice Weight","scheduler",34)},{id:"ivx-cfs-vruntime",prompt:"In classic Linux CFS (before the switch to EEVDF in kernel 6.6), which runnable task is picked to run next?",options:["The one with the smallest virtual runtime, so tasks that have received less weighted CPU time go first","The one that arrived first","The one with the shortest total burst","The one chosen at random each tick"],answer:0,explain:"CFS tracks each task's vruntime, its CPU time scaled by the inverse of its weight, and keeps runnable tasks in a red-black tree ordered by it. The leftmost node (smallest vruntime) has been treated least fairly so far, so it runs next. Heavier (lower nice) tasks accumulate vruntime more slowly and therefore run more often. Linux 6.6 replaced this pick with EEVDF (see ivx-eevdf-pick).",move:s("Fair Share","scheduler",36)},{id:"ivx-eevdf-pick",prompt:"Since Linux 6.6 the default fair scheduler is EEVDF. Which runnable task does it pick next?",options:["The task with the smallest vruntime, exactly as CFS did","The task with the highest nice value","Among tasks that are eligible (not owed negative lag), the one with the earliest virtual deadline","The task with the shortest remaining burst"],answer:2,explain:"EEVDF (Earliest Eligible Virtual Deadline First, mainline since Linux 6.6) gives each task a lag: the CPU time it should have received minus what it got. A task is eligible while its lag is not negative. Each task's virtual deadline is its eligible time plus its requested slice divided by its weight, and the scheduler runs the eligible task with the earliest deadline. A short requested slice therefore gets lower latency without extra CPU share, which CFS's vruntime-only pick could not express. Nice weights are unchanged. (As of October 2026.)",move:s("Virtual Deadline","scheduler",38)},{id:"ivx-rt-class",prompt:"Why can a runaway SCHED_FIFO real-time task freeze a Linux system, while a runaway normal task cannot?",options:["A SCHED_FIFO task outranks all normal tasks and runs until it blocks or yields, with no time slice, so normal tasks may never get the CPU","Real-time tasks use more memory","SCHED_FIFO disables interrupts permanently","Normal tasks are always killed first"],answer:0,explain:"Real-time classes (SCHED_FIFO, SCHED_RR) always take precedence over SCHED_OTHER tasks. SCHED_FIFO has no quantum: the task keeps the CPU until it blocks, yields or a higher real-time priority becomes runnable. A busy loop at that priority starves everything below it, which is why the kernel offers RT throttling and why RT priorities need privilege.",move:s("Strict Rank","scheduler",38)},{id:"ivx-affinity",prompt:"Why might pinning a thread to one CPU core (CPU affinity) improve performance?",options:["It keeps the thread's working set warm in that core's caches and avoids migration costs","It gives the thread a higher priority","It lets the thread use more memory","It removes the need for locks"],answer:0,explain:"When the scheduler migrates a thread, its data in the old core's L1/L2 caches (and TLB entries) are lost, so it restarts with cache misses. Affinity avoids that, which also helps NUMA locality. The cost is less flexibility: a pinned thread cannot move to an idle core, so load can become unbalanced.",move:s("Core Lock","scheduler",34)},{id:"ivx-load-avg",prompt:"A 4-core machine shows a load average of 8.0 for a long time. What does that most plausibly mean?",options:["On average about 8 tasks are running or waiting to run (or in uninterruptible I/O), so demand is roughly twice the CPU capacity","The CPUs are 8% busy","Eight cores are idle","The machine has 8 GB of free memory"],answer:0,explain:"On Linux the load average counts tasks that are runnable or in uninterruptible sleep, averaged over 1, 5 and 15 minutes. Load of 8 on 4 cores means about two tasks per core are competing, so work queues up. Load is not a percentage; check CPU utilization and I/O wait to tell whether the cause is CPU saturation or blocked disk I/O.",move:s("Load Meter","scheduler",34)}];e.s(["f",0,a])},21595,e=>{e.s(["O",0,{BIOS:["Power on: the CPU starts running firmware from ROM","The BIOS runs the power-on self-test (POST)","The BIOS loads the 512-byte boot block from the disk's MBR","The boot loader (e.g. GRUB) loads the kernel image into memory","The kernel initializes the hardware and mounts the root file system","The kernel starts init (PID 1), the first user-mode process"],UEFI:["Power on: the CPU starts running firmware from flash","The UEFI firmware runs the power-on self-test (POST)","UEFI loads the boot loader file from the EFI System Partition","The boot loader loads the kernel image into memory","The kernel initializes the hardware and mounts the root file system","The kernel starts init (PID 1), the first user-mode process"]},"k",0,[{text:"A key is pressed on the keyboard",interrupt:!0},{text:"A disk read finishes",interrupt:!0},{text:"The hardware timer goes off",interrupt:!0},{text:"A network packet arrives",interrupt:!0},{text:"The mouse is moved",interrupt:!0},{text:"A USB stick is plugged in",interrupt:!0},{text:"The program divides by zero",interrupt:!1},{text:"The program executes the syscall instruction",interrupt:!1},{text:"The program touches a page that isn't in memory",interrupt:!1},{text:"The program runs a privileged instruction in user mode",interrupt:!1},{text:"The program hits a debugger breakpoint instruction",interrupt:!1},{text:"The program dereferences an invalid address",interrupt:!1}],"g",0,[{text:"Set the value of the timer",privileged:!0},{text:"Turn off interrupts",privileged:!0},{text:"Clear all of physical memory",privileged:!0},{text:"Modify the device-status table",privileged:!0},{text:"Send a command to the disk controller",privileged:!0},{text:"Load the page-table base register",privileged:!0},{text:"Set the mode bit to kernel mode",privileged:!0},{text:"Halt the CPU",privileged:!0},{text:"Read the clock",privileged:!1},{text:"Execute the trap (syscall) instruction",privileged:!1},{text:"Add two registers",privileged:!1},{text:"Call a function in the same program",privileged:!1},{text:"Load a word from the program's own memory",privileged:!1},{text:"Compare two values and branch",privileged:!1}],"z",0,(e,t)=>e*t/1e4])}])})();